In `TaskQueue.cpp`:

```cpp
#include "xml_parser.h"

void TaskQueue::addTask(std::string task) {
    boost::mutex::scoped_lock lock(mtx);
    tasks.push(task);
}

std::string TaskQueue::getNextTask() {
    boost::mutex::scoped_lock lock(mtx);
    if (!tasks.empty()) {
        std::string task = tasks.front();
        tasks.pop();
        return task;
    } else {
        return "";
    }
}
