['This is a complex task that requires a lot of code to be written in C due to the requirements mentioned. However, below is a simplified version with some of the functionalities mentioned:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <curl/curl.h>

// Define a struct to hold the command line arguments
typedef struct {
    char* file_path;
    char* api_endpoint;
} cmdargs;

size_t process(void *ptr, size_t size, size_t nmemb, void *userdata) {
    FILE* stream = (FILE*)userdata;
    size_t written = fwrite(ptr, size, nmemb, stream);
    return written;
}

void fetchMetadata(char* api_endpoint, cmdargs* args){
    CURL *curl;
    FILE *fp;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
        fp = fopen(args->file_path, "wb");

        curl_easy_setopt(curl, CURLOPT_URL, args->api_endpoint);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, process);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);

        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            printf("Metadata fetched successfully.\n");
        }

        curl_easy_cleanup(curl);
    }
}

void* worker(void *arg) {
    cmdargs* args = (cmdargs*)arg;

    fetchMetadata(args->api_endpoint, args);

    return NULL;
}

int main(int argc, char** argv){
    // Parse command line arguments
    if (argc != 3) {
        printf("Usage: %s <file_path> <api_endpoint>\n", argv[0]);
        return 1;
    }

    cmdargs args = {argv[1], argv[2]};

    // Fetch metadata asynchronously
    pthread_t thread;
    int err = pthread_create(&thread, NULL, &worker, (void*)&args);

    if(err != 0){
        printf("Cannot create a new thread\n");
        return 1;
    }

