#include <string>
#include <future>
#include <vector>
#include <mutex>

class StringManager {
public:
    // Insert a string after a specified search string or append if not found.
    void insertOrAppend(const std::string& searchString, const std::string& newString) {
        mtx_.lock();  // lock for thread safety
        auto it = std::find(strings_.begin(), strings_.end(), searchString);

        if (it != strings_.end()) {
            strings_.insert_after(it, newString);
        } else {
            strings_.push_front(newString);
        }
        mtx_.unlock();  // unlock after operation is done.
    }

    // Validates data from external source asynchronously without blocking the main thread.
    std::future<bool> validateDataFromSourceAsync(const std::string& searchString) {
       return std::async(std::launch::async, [this, &searchString]() -> bool {
            // Simulate an external data source call with a sleep.
            std::this_thread::sleep_for(std::chrono::milliseconds(100));  

            if (externalDataSource_.find(searchString) != std::string::npos) {
                return true;  // Validated successfully
            } else {
                errorLog_.push_back("Failed to validate data from source: " + searchString);
                return false;
            }
        });
    }

private:
    std::forward_list<std::string> strings_;
    std::mutex mtx_;  // For concurrent access and thread safety.
    std::string externalDataSource_;  // Simulated as a string for this example, could be another object or function that interacts with an actual data source.
    std::vector<std::string> errorLog_;  // To log errors for debugging.
};
