        ResponseEntity<String> response;
        try {
            response = restTemplate.exchange(API_URL + "/" + id, HttpMethod.PUT, entity, String.class);
        } catch (ResourceAccessException e) {
            // Handle network errors here
            return new ResponseEntity<>("Network Error", HttpStatus.INTERNAL_SERVER_ERROR);
        }

        if (!response.getStatusCode().is2xxSuccessful()) {
            // Handle non-success responses from the API
            return new ResponseEntity<>(response.getBody(), response.getStatusCode());
        }

        String md5Hash = DigestUtils.md5Hex(jsonPayload);
        // Log the MD5 hash of the updated JSON string for auditing purposes

        // Return only the modified fields from the updated resource
        return new ResponseEntity<>(response.getBody(), HttpStatus.OK);
    }

