// Callback function for CURL to write received data
size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    // Calculate the total number of items here using the received data
    return size * nmemb; 
}

int LoadResourceBundleFromUrl(char *url){
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);

        // Set the callback function for handling received data
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);

        res = curl_easy_perform(curl);

        /* Check for errors */ 
        if(res != CURLE_OK) {
          fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
          return res; // return error code
        }

        /* always cleanup */ 
        curl_easy_cleanup(curl);
    }

    return CURLE_OK; // return success code
}
