import java.io.IOException;

public class ObservabilityService {
    private String configURL;
    private String analyticsURL;
    private String notificationURL;

    // Constructor to set API URLs
    public ObservabilityService(String configURL, String analyticsURL, String notificationURL) {
        this.configURL = configURL;
        this.analyticsURL = analyticsURL;
        this.notificationURL = notificationURL;
    }

    // Method to make HTTP GET request and return response as a string
    private String get(String url) throws IOException {
        CloseableHttpClient httpclient = HttpClients.createDefault();
        HttpGet httpget = new HttpGet(url);
        CloseableHttpResponse response = null;

        try {
            response = httpclient.execute(httpget);
            return EntityUtils.toString(response.getEntity());
        } finally {
            if (response != null) {
                response.close();
            }
        }
    }

    // Method to handle calls to config API
    public String callConfigAPI() throws IOException {
        return get(configURL);
    }

    // Method to handle calls to analytics API
    public String callAnalyticsAPI() throws IOException {
        return get(analyticsURL);
    }

    // Method to handle calls to notification API
    public String callNotificationAPI() throws IOException {
        return get(notificationURL);
    }
}
