#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Set up configuration service client, 
    // get base URL and default headers here

    let mut base_url = match fetch_base_url() {
        Ok(url) => url,
        Err(_) => return Err("Failed to fetch base URL".into()),
    };

    let mut headers = match fetch_headers() {
        Ok(hdr) => hdr,
        Err(_) => return Err("Failed to fetch headers".into()),
    };

    // Create a TlsConnector for the client.
    let connector = TlsConnector::builder().unwrap(); 

    // Configure TLS version and ciphers if needed
    //connector.configure()...;

    // Use TlsConnector in the reqwest ClientBuilder
    let client: Client = Client::builder()
        .connector(native_tls::NativeTlsConnector::from(connector))
        .build()?;

    loop {
        // Fetch data from configuration service and use it to update base URL and headers
