```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <mutex>
#include "AttackAPI.h" // This is a hypothetical API you would need to create yourself or use from a third party library
#include "Logger.h"
#include "Database.h"

using namespace std;

class Attack {
public:
    string name;
    int cooldown;
    bool inCooldown;
    chrono::system_clock::time_point startTime;
};

class CombatSystem {
private:
    vector<Attack> attacks;
    AttackAPI api;
    Logger logger;
    Database database;
    mutex mtx;

public:
    void addAttack(const string& name, int cooldown) {
        if (attacks.size() < 10) {
            attacks.push_back({name, cooldown, false});
        } else {
            cout << "Cannot add more than 10 attacks" << endl;
        }
    }

    void selectAttack(int index) {
        mtx.lock(); // Lock the mutex to prevent simultaneous access from different threads

        if (index >= 0 && index < attacks.size()) {
            Attack& selected = attacks[index];

            if (!selected.inCooldown) {
                selected.startTime = chrono::system_clock::now();
                selected.inCooldown = true;

                // Start a new thread to handle cooldown
                thread cd([&]() { 
                    this_thread::sleep_for(chrono::seconds(selected.cooldown));
                    mtx.lock(); // Lock the mutex before modifying shared data
                    selected.inCooldown = false;
                    mtx.unlock(); // Unlock the mutex after modifying shared data
                });

                cd.detach(); // Detaching the thread ensures it runs independently of main thread
            } else {
                logger.logError("Attack " + selected.name + " is in cooldown");
            }
        } else {
            logger.logError("Invalid attack selection");
        }

        mtx.unlock(); // Unlock the mutex once we're done modifying shared data
    }
};
```
This provides a basic structure for your combat system with an added thread to handle cooldowns of each attack. The actual implementation would need significant more effort in terms of error handling, database interaction, API calls, logging and testing etc. Also note that I'm assuming you have defined `Logger`, `Database` and `AttackAPI` classes/interfaces which are not part of the standard library and would be needed to be defined separately based on your requirements.
']

