['Here's a basic implementation using JavaScript (Node.js) for the problem statement. Please note that this code may need to be adjusted based on specific requirements of the external APIs you are integrating with and the weighting scheme used for computing composite scores.

```javascript
const fetch = require('node-fetch');
const Bottleneck = require("bottleneck/es5"); // For rate limiting

// Weightage can be adjusted based on requirement
const WEIGHTAGE_ACTIVITY = 0.3;
const WEIGHTAGE_ENGAGEMENT = 0.4;
const WEIGHTAGE_SOCIAL_MEDIA = 0.3;

// Function to fetch user profile asynchronously
async function fetchUserProfileAsync(userId, apiEndpoint) {
    let response = await fetch(apiEndpoint + '/' + userId);

    if (!response.ok) throw new Error('HTTP error ' + response.status);
    return await response.json(); // Assuming API returns JSON data
}

// Function to compute composite score based on weightage
function computeCompositeScore(profileData) {
    let activity = profileData.activityLevel || 0;
    let engagementTime = profileData.engagementTime || 0;
    let socialMediaPresence = profileData.socialMediaPresence || 0;

    return (activity * WEIGHTAGE_ACTIVITY + 
            engagementTime * WEIGHTAGE_ENGAGEMENT +
            socialMediaPresence * WEIGHTAGE_SOCIAL_MEDIA);
}

// Rate limiting to control the number of requests made in a certain time period
const limiter = new Bottleneck({ maxConcurrent: 5, minTime: 100 });

async function serviceHandler(userIds, apiEndpoint) {
    let userPromises = [];

    // Fetching and computing score for each user concurrently
    for (let id of userIds) {
        userPromises.push(limiter.schedule(() => fetchUserProfileAsync(id, apiEndpoint)
            .then((profileData) => computeCompositeScore(profileData))));
    }

    return Promise.all(userPromises); // Wait for all the promises to resolve
}

// Testing service handler
async function testServiceHandler() {
    let userIds = [1, 2, 3];
    let apiEndpoint = 'https://api.example.com/users';

    try {
        console.log(await serviceHandler(userIds, apiEndpoint));
    } catch (e) {
        console.error('Error in service:', e);
    }
}

testServiceHandler();
```

This code is a starting point and doesn't handle authentication or error recovery which you would need to add based on the specifics of each API endpoint. The rate limit is implemented using Bottleneck, which allows us to control the number of requests made in a certain time period. This helps in preventing system overload when dealing with multiple requests at once. 

The weightage for calculating composite score is set as constants and can be adjusted based on requirement. The serviceHandler function fetches user profiles concurrently, computes scores, and returns all the scores once they are computed. It uses Bottleneck to manage rate limiting and ensure efficient concurrency control when dealing with a large number of requests.
']

