```c
#include <stdio.h>
#include <string.h>
#include <pthread.h>

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Mockup of a logging function, replace with actual library call
int log_warning(const char* message) {
    printf("Warning: %s\n", message);
    return 0;
}

int log_error(const char* message) {
    printf("Error: %s\n", message);
    return -1;
}

char* safe_copy_string(const char* src, size_t limit, char* dest, size_t capacity) {
    if (src == NULL || dest == NULL) {
        log_error("Null pointer detected");
        return NULL;
    } 

    if (capacity == 0) {
        log_error("Invalid buffer capacity");
        return NULL;
    }

    pthread_mutex_lock(&lock);

    size_t length = strlen(src);

    if (length > limit) {
        log_warning("Source string exceeds the size limit. Only first part will be copied.");
        length = limit;
    }

    if (length >= capacity) {
        log_error("Buffer is insufficient");
        pthread_mutex_unlock(&lock);
        return NULL; 
    }

    strncpy(dest, src, length);
    dest[length] = '\0';

    pthread_mutex_unlock(&lock);

    return dest;
}
```
This code implements the requirements: it locks the thread for ensuring thread safety in a multi-threaded environment. It also logs errors or warnings depending on conditions (e.g., if source string exceeds buffer size limit). The library call `log_warning` and `log_error` are merely placeholders; you should replace them with actual function calls to your logging library.

