['Your request is quite complex and involves multiple components such as file management, logging system, error handling and WMI communication which are not directly possible via console and text editor in C#. You may need to divide it into several smaller tasks or parts and implement them separately. Here's a simple implementation of the 'WebDeploymentManager' class that integrates with a configuration service using RESTful API calls:

```csharp
using System;
using System.IO;
using System.Net;
using System.Management; // WMI namespace
using Newtonsoft.Json; // JSON serialization/deserialization

public class WebDeploymentManager
{
    private readonly IConfigurationService _configurationService;
    private readonly ILoggingService _loggingService;

    public WebDeploymentManager(IConfigurationService configurationService, ILoggingService loggingService)
    {
        _configurationService = configurationService ?? throw new ArgumentNullException(nameof(configurationService));
        _loggingService = loggingService ?? throw new ArgumentNullException(nameof(loggingService));
    }

    public void DeployWebApplication(string applicationPath, string webSiteName)
    {
        if (string.IsNullOrEmpty(applicationPath)) 
            throw new ArgumentException("Invalid path", nameof(applicationPath));

        if (string.IsNullOrEmpty(webSiteName)) 
            throw new ArgumentException("Invalid web site name", nameof(webSiteName));

        try
        {
            var configFiles = Directory.GetFiles(applicationPath, "*config");

            foreach (var file in configFiles)
            {
                _configurationService.ProvisionConfigurationFile(file);
            }

            using (var managementScope = new ManagementScope($"\\\\localhost\\root\\WebAdministration"))
            {
                var webApplicationClass = new ManagementPath("IIsWebServer")
                    .GetRelatedClasses(managementScope)
                    .FirstOrDefault(c => c.Name == "WebApplication");

                if (webApplicationClass != null) 
                {
                    var inParams = managementScope.CreateMethodParameters("AppCreate3");

                    inParams["Site"] = webSiteName;
                    inParams["p_appPath"] = $"/{Path.GetFileName(applicationPath)}";
                    inParams["p_physicalPath"] = applicationPath;

                    var outParams = managementScope.InvokeMethod(webApplicationClass, "AppCreate3", inParams, null);

                    if ((UInt32)outParams["returnValue"]) 
                        throw new Exception("Failed to create web application");
                }
            }
        }
        catch (Exception ex)
        {
            _loggingService.LogError(ex, $"Error deploying web app '{applicationPath}'");
            throw;
        }
    }
}
``` 

