using System.Threading;
using System.Collections.Concurrent;

public class SecureDataProcessor 
{
    private readonly ConcurrentDictionary<string, byte[]> _downloadedFilesCache = new ConcurrentDictionary<string, byte[]>();

    public T DeserializeFromS3<T>(string bucketName, string key, string encryptionKey)
        where T : class
    {
        var downloadedData = DownloadEncryptedFileFromS3(bucketName, key);
        var decryptedData = DecryptAesCbc(downloadedData, Convert.FromBase64String(encryptionKey));

        // Assuming you have a method that converts byte[] to T type object
        return BytesToObject<T>(decryptedData); 
    }

    private byte[] DownloadEncryptedFileFromS3(string bucketName, string key)
    {
        using var client = new AmazonS3Client(RegionEndpoint.USEast1);
        var request = new GetObjectRequest { BucketName = bucketName, Key = key };

        try
        {
            byte[] downloadedData;

            if (!_downloadedFilesCache.TryGetValue(key, out downloadedData)) 
            {
                using var response = client.GetObjectAsync(request).Result;
                using var memoryStream = new MemoryStream();
                response.ResponseStream.CopyTo(memoryStream);
                downloadedData = memoryStream.ToArray();

                // Use a thread-safe operation to ensure atomicity and cache the result 
                _downloadedFilesCache.AddOrUpdate(key, k => downloadedData, (k, v) => downloadedData);
            }

            return downloadedData;
        }
        catch (Exception ex)
        {
            // Handle exceptions
            Console.WriteLine("Error downloading file from S3: " + ex.Message);
            throw;
        } 
    }

    private byte[] DecryptAesCbc(byte[] encryptedData, byte[] encryptionKey) 
