['The following classes and methods describe a basic skeleton of how such a system might be implemented in C#, but actual implementation would require careful consideration of all factors mentioned above. The code below does not take into account many factors mentioned above including performance optimization, thread-safety, exception handling, logging etc., therefore is not ready to use in production environment.

```CSharp
using System;
using System.IO;
using System.Text;
using System.Threading.Tasks;
using System.Security.Cryptography;
using Microsoft.Extensions.Logging;

public class SecurityAndDataProcessor
{
    private readonly TripleDESCryptoServiceProvider _tripleDes = new TripleDESCryptoServiceProvider();
    private readonly ILogger<SecurityAndDataProcessor> _logger;

    public SecurityAndDataProcessor(ILogger<SecurityAndDataProcessor> logger, byte[] key, byte[] iv)
    {
        this._tripleDes.Key = key;
        this._tripleDes.IV = iv;
        this._logger = logger;
    }

    public int FindMaxIntegerInFile(string path)
    {
        if (!File.Exists(path))
        {
            _logger.LogError("File does not exist: " + path);
            return -1;
        }

        try
        {
            var lines = File.ReadAllLines(path);

            int maxValue = int.MinValue;

            foreach (var line in lines)
            {
                if (!int.TryParse(line, out var value))
                {
                    _logger.LogError("Invalid data in file: " + path);
                    return -1;
                }

                maxValue = Math.Max(maxValue, value);
            }

            return maxValue;
        }
        catch (Exception ex)
        {
            _logger.LogError("Failed to read file: " + path, ex);
            return -1;
        }
    }

    public async Task ProcessBatchOfFiles(string directoryPath, int batchSize = 100)
    {
        var files = Directory.GetFiles(directoryPath);

        for (var i = 0; i < files.Length; i += batchSize)
        {
            var tasks = new List<Task>();

            for (var j = 0; j < batchSize && i + j < files.Length; j++)
            {
                var filePath = files[i + j];

                tasks.Add(Task.Run(() => FindMaxIntegerInFile(filePath)));
            }

            await Task.WhenAll(tasks);
        }
    }

    public string DecryptBase64Message(string encryptedData)
    {
        var cipherTextBytes = Convert.FromBase64String(encryptedData);

        using (var decryptor = _tripleDes.CreateDecryptor(_tripleDes.Key, _tripleDes.IV))
        {
            byte[] originalMessage;

            using (MemoryStream memoryStream = new MemoryStream())
            {
                using (CryptoStream cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Write))
                {
                    cryptoStream.Write(cipherTextBytes, 0, cipherTextBytes.Length);
                    cryptoStream.FlushFinalBlock();

                    originalMessage = memoryStream.ToArray();
                }
            }

            return Encoding.UTF8.GetString(originalMessage);
        }
    }
}
```
The class `SecurityAndDataProcessor` is designed to read and process integer values from a CSV file, as well as decrypt Base64-encoded messages using Triple DES encryption with a given key and initialization vector (IV). 

Please note that the code above does not take into account many factors mentioned above including performance optimization, thread safety, exception handling, logging etc., therefore is not ready to use in production environment. The actual implementation would need careful consideration of all these factors.
']

