        return ErrorCode::EMPTY_PASSWORD;
    }

    // Assume we have a rule that all connections must start with 'CONN_'
    const std::string CONNECTION_PREFIX = "CONN_";

    if (connection.title.find(CONNECTION_PREFIX) != 0) {
        return ErrorCode::INVALID_CONNECTION_TITLE;
    }

    // Check callback function is not null
    if (!callback) {
        return ErrorCode::NULL_CALLBACK;
    }

    return ErrorCode::SUCCESS;
}

