#include <random>
#include <openssl/rand.h>
#include <botan/auto_rng.h>
#include <atomic>
#include <vector>
#include <stdexcept>

enum class RNGAlgorithm {MersenneTwister, AESPRNG};

class SecureRandomEngine 
{
public:
    SecureRandomEngine(RNGAlgorithm algo = RNGAlgorithm::MersenneTwister) : algo_(algo) {}

    void setSeed(unsigned int seed) { 
        if (seed == 0) throw std::invalid_argument("Invalid seed");
        mt_.seed(seed); 
    }

    void reseed() {
        unsigned char buf[32];
        RAND_bytes(buf, sizeof(buf));
        mt_.seed((int*)buf); // Use OpenSSL or Botan's secure random number generator for better seeding.
    }

    int generateInt(int minVal, int maxVal) { 
        std::uniform_int_distribution<> dist(minVal, maxVal);
        return dist(mt_); 
    }

    double generateDouble(double minVal, double maxVal) { 
        std::uniform_real_distribution<> dist(minVal, maxVal);
        return dist(mt_); 
    }

private:
    RNGAlgorithm algo_;
    std::mt19937 mt_; // default algorithm is Mersenne Twister
};
```

This example uses the Mersenne Twister as the default random number generator and OpenSSL for seeding. It can generate integers and doubles using uniform distributions. The RNGAlgorithm enum could be expanded to include other algorithms, which would require adding support for them in the `generateInt` and `generateDouble` methods.

