```java
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import javax.validation.Valid;
import java.util.Optional;

@RestController
public class ResourceController {
    @Autowired
    private ResourceRepository resourceRepository;

    // PUT endpoint to update existing resources
    @PutMapping("/resources/{id}")
    public ResponseEntity<Resource> updateResource(@PathVariable Long id, @Valid @RequestBody Resource updatedResource) {
        Optional<Resource> optionalResource = resourceRepository.findById(id);

        if (!optionalResource.isPresent()) 
            return ResponseEntity.notFound().build();

        // Merge the incoming updates with existing data
        Resource existingResource = optionalResource.get();
        existingResource.mergeWithUpdates(updatedResource); 

        // Validate changes against predefined schemas
        if (!existingResource.validate()) {
            return ResponseEntity.badRequest().build();
        }

        // Save the updated resource
        Resource saved = resourceRepository.save(existingResource);
        return ResponseEntity.ok(saved);
    }
}
```
And here's a very simplified version of `Resource` and `mergeWithUpdates` method:

