```Csharp
public class UserManager : IUserManager
{
    private readonly UserContext _context;

    public UserManager(UserContext context)
    {
        _context = context;
    }

    public async Task<bool> AuthenticateAsync(string username, string password)
    {
        var user = await _context.Users.FindAsync(username);

        if (user == null) return false;

        if (user.LockedOutUntil > DateTime.Now) 
            throw new LockoutException();

        if (user.FailedAttempts >= Policy.MaximumRetryThreshold) {
            user.LockedOutUntil = DateTime.Now.AddMinutes(Policy.LockoutDuration);
            await _context.SaveChangesAsync();
            throw new LockoutException();
        }

        if (user.Password != password) 
        {
            user.FailedAttempts++;
            await _context.SaveChangesAsync();
            return false;
        }

        user.LastLogin = DateTime.Now;
        user.FailedAttempts = 0;
        await _context.SaveChangesAsync();

        return true;
    }

    // Other methods like AddUser, UpdatePassword etc
}
```
