        return ['input1', 'input2', 'input3']  # high priority fields
    elif user_config['networkCondition'] == 'good' and user_config['deviceType'] == 'Desktop':
        return ['input4', 'input5', 'input6']  # medium priority fields
    else:
        return ['input7', 'input8', 'input9']  # low priority fields
