    MetaRepo meta_repo;
    DTCLayer dtc_layer;
    std::mutex rename_mutex; // For thread safety during renames
    std::unordered_map<std::string, std::atomic<int>> version_numbers; // Map to store and increment versions
    std::filesystem::path dir_path;
    std::chrono::milliseconds ms_timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()); // Timestamp for versioning

public:
    FileManager(const std::filesystem::path& path) : dir_path(path){} 

    OperationStatus renameFile(const std::string& oldName, const std::string& newNameTemplate);
};

OperationStatus FileManager::renameFile(const std::string& oldName, const std::string& newNameTemplate) {
    auto ms_timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()); // Get timestamp for current rename operation

    // Ensure thread-safe renaming
    const std::lock_guard<std::mutex> lock(rename_mutex); 

    auto oldPath = dir_path / oldName;
    if (!std::filesystem::exists(oldPath)) {
        return OperationStatus::FAILURE; // File not found
    }

    std::string newFileNameWithVersion = 
        std::regex_replace(newNameTemplate, 
                           std::regex("\\$timestamp"), ms_timestamp.count()) + 
        "_v" + std::to_string(version_numbers[oldName]++); // Increment version number and add to filename
    auto newPath = dir_path / newFileNameWithVersion;

    try {
      vcs.renameFile(oldPath, newPath);
      meta_repo.updateMetaData(newPath);
      dtc_layer.loadBitmap(newPath);

      return OperationStatus::SUCCESS; 
