```python
import logging
import time
from requests_oauthlib import OAuth2Session
from decouple import config

# Logging Configuration
class CustomLogger:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)

    def log(self, level, message):
        if level == 'INFO':
            self.logger.info(message)
        elif level == 'ERROR':
            self.logger.error(message)
        # Add other levels as needed

# External Event Management System Configuration
class ExternalEventSystem:
    def __init__(self):
        client_id = config('CLIENT_ID')
        client_secret = config('CLIENT_SECRET')
        self.oauth = OAuth2Session(client_id)

    def send_log(self, log_entry):
        url = "https://external-event-management-system/api"
        headers = {'Content-Type': 'application/json'}
        max_attempts = 5
        backoff_factor = 0.5

        for attempt in range(max_attempts):
            try:
                response = self.oauth.post(url, json=log_entry, headers=headers)
                response.raise_for_status()  # Raise an exception for unsuccessful requests
                return True
            except Exception as e:
                if attempt < max_attempts - 1:
                    time.sleep((backoff_factor * (2 ** attempt)))  # Exponential backoff
                    continue
                else:
                    raise e  # Failed after all attempts
        return False

# Configuration and Usage
logger = CustomLogger()
event_system = ExternalEventSystem()
log_entry = {"level": "INFO", "message": "Test log entry"}
successful_send = event_system.send_log(log_entry)
if successful_send:
    logger.log('INFO', 'Log sent successfully')
else:
    logger.log('ERROR', 'Failed to send log')
```

