['Creating such an extensive library would be beyond the scope of this platform. However, I can provide you with a very simplified example to illustrate some key concepts using C++11 and libcurl for network requests.

Please note that this is not a production-ready code, it's just for illustrative purposes:

```cpp
#include <iostream>
#include <string>
#include <thread>
#include <curl/curl.h>
#include <json/json.h>

// Global curl handle initialization
CURL* curl = curl_easy_init(); 
std::mutex mtx; // Mutex for thread safety

Json::Value fetchWeather(const std::string& location) {
    if (!curl) { return Json::objectValue; }

    std::lock_guard<std::mutex> lock(mtx);  // Lock guard ensures that only one thread can execute at a time.

    curl_easy_setopt(curl, CURLOPT_URL, ("http://api.weatherstack.com/current?access_key=YOUR_ACCESS_KEY&query=" + location).c_str());

    // Perform the request, res will get the return code
    auto res = curl_easy_perform(curl);

    // Check for errors
    if (res != CURLE_OK) {
        std::cerr << "CURL Error: " << curl_easy_strerror(res) << '\n';
        return Json::objectValue;
    }

    long responseCode; 
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &responseCode);

    if (responseCode != 200) {
        std::cerr << "HTTP Response Error: " << responseCode << '\n';
        return Json::objectValue;
    } 

