class ConfigurationService {
public:
    virtual void fetch() = 0;
};

// A simple implementation of a configuration service
class SimpleConfigurationService : public ConfigurationService {
private:
    std::string config;
public:
    void fetch() override {
        // Fetch from external API and update the cache. 
        // Include error handling and edge cases for network failures, inconsistent data etc.
    }
};

// A simple implementation of a caching system
class SimpleCachingSystem {
private:
    std::unordered_map<std::string, ConfigurationService*> cache;
    std::mutex mtx;  // Mutex for thread safety
public:
    void update(const std::string& key, ConfigurationService* value) {
        std::lock_guard<std::mutex> lock(mtx);
        if (cache.find(key) == cache.end()) {
            cache[key] = value;
        } else {
            delete cache[key];  // Assuming old configs can be deleted to free up memory
            cache[key] = value;
        }
    }

    ConfigurationService* get(const std::string& key) {
        std::lock_guard<std::mutex> lock(mtx);
        if (cache.find(key) == cache.end()) {
            return nullptr;  // Not in cache
        } else {
            return cache[key];  // Returns a copy, actual configuration is still stored in cache
        }
    }
};

// A simple implementation of concurrent processing
class SimpleConcurrencySystem {
private:
    std::vector<std::thread> threads;
public:
    void start(ConfigurationService* service) {
        // Start a new thread to fetch the configuration from an external API 
        threads.push_back(std::thread(&ConfigurationService::fetch, service));
    }

    void joinAll() {
        for (auto& th : threads) {
            if (th.joinable()) th.join();
        }
    }
};

int main() {
    SimpleConcurrencySystem sys;
    SimpleCachingSystem cache;
    ConfigurationService* service = new SimpleConfigurationService();  // Use a factory here to create services of different types

    // Fetch the configuration in a separate thread and update the cache
    sys.start(service);
    std::this_thread::sleep_for (std::chrono::seconds(1)); // Just to make sure that config is fetched before get() call
    cache.update("key", service);

    // Get configuration from cache in main thread
    ConfigurationService* config = cache.get("key"); 

    sys.joinAll();  // Wait for all threads to finish
}
```

Please note that this is a simplified example and does not include all the features mentioned in your task such as comprehensive unit tests, notifications system, better caching system, handling different edge cases, etc. It's recommended to use an existing library or framework if possible as they often provide robust solutions for these tasks. C++ frameworks like POCO C++ can be used for network programming, and Boost.Asio can be used for multi-threading.
