["It's not possible for me to create a complete solution here due to complexity of the problem, but I can give you an example of how you could start implementing such a system using C and POSIX threads. Please note that this is very simplified version and doesn't include all the features you mentioned like load balancing, failover strategies, security measures or error recovery mechanisms:

```C
#include <stdlib.h>
#include <pthread.h>
#include <string.h>

// Define a node in our queue
typedef struct Node {
    char* data; // this should be your XML string
    struct Node* next;
} Node_t;

// Our Queue and its operations
typedef struct Queue {
    pthread_mutex_t lock;
    Node_t *head, *tail;
} Queue_t;

Queue_t* createQueue() {
    Queue_t* q = malloc(sizeof(Queue_t));
    memset(q, 0, sizeof(Queue_t)); // initialize all fields to zero
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

void enqueue(Queue_t* q, char* data) {
    Node_t* newNode = malloc(sizeof(Node_t)); // allocate memory for the new node
    strcpy(newNode->data, data); // copy the xml string into the node
    pthread_mutex_lock(&q->lock);
    if (q->tail) {
        q->tail->next = newNode;
        q->tail = newNode;
    } else {
        q->head = q->tail = newNode;
    }
    pthread_mutex_unlock(&q->lock);
}

char* dequeue(Queue_t* q) {
    char* data = NULL;
    pthread_mutex_lock(&q->lock);
    if (q->head) { // only proceed if queue is not empty
        Node_t* nodeToRemove = q->head;
        data = malloc(strlen(nodeToRemove->data) + 1); // allocate memory for the xml string
        strcpy(data, nodeToRemove->data); // copy xml string into return variable
        if (q->tail == q->head) { // this was the only element in queue
            q->tail = NULL;
        }
        q->head = nodeToRemove->next;
        free(nodeToRemove); // deallocate memory for removed node
    }
    pthread_mutex_unlock(&q->lock);
    return data;
}
```
This is a very basic thread-safe queue implementation where you can add and remove XML strings from the queue. You would need to add more complex logic to parse these strings and distribute them between multiple threads for processing, which is not included in this simple example. Also note that error handling and resource management are absent in this code, but should be added according to your project requirements.
"]

