// Thread pool
typedef struct {
    pthread_t thread;
    int id;
} WorkerThread;

// Task structure
typedef struct {
    int taskId;
    void *taskData;
} Task;

void* worker(void *arg) {
    WorkerThread *wt = (WorkerThread *) arg;

    while(1) {
        // Acquire task from queue synchronously. This is a simplistic example, and actual implementation would require thread safety mechanisms like mutexes or semaphores.
        Task *task = acquireTask(); 

        if(task == NULL) {
            break;
        }

        // Process the task (which may involve parsing an XML file). This is just a placeholder for actual processing logic.
        processXML(wt->id, task); 
    }

    return NULL;
}

// Function to initialize and start threads in the pool
void initThreadPool(int numWorkers) {
    WorkerThread *workers = malloc(sizeof(WorkerThread) * numWorkers);

    for(int i = 0; i < numWorkers; ++i) {
        workers[i].id = i;

        if(pthread_create(&workers[i].thread, NULL, worker, &workers[i])) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }

    // Wait for all threads to finish
    for(int i = 0; i < numWorkers; ++i) {
        if(pthread_join(workers[i].thread, NULL)) {
            fprintf(stderr, "Error joining thread\n");
            return;
        }
    }

    free(workers);
