#include <pthread.h>
#include <semaphore.h>

typedef struct Queue {
    int head, tail, size;
    unsigned capacity;
    void **array;
    pthread_mutex_t lock;
    sem_t *full, *empty;
} Queue;

Queue* createQueue(unsigned capacity);
