```cpp
#include <atomic>
#include <condition_variable>
#include <future>
#include <mutex>
#include <queue>
#include <thread>

// For simplicity, assume multimedia files are represented by strings here
using MultimediaFile = std::string;

class WorkerPool {
public:
    explicit WorkerPool(size_t numThreads) : shutdown_(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            threads_.emplace_back(&WorkerPool::workerFunction, this);
        }
    }

    ~WorkerPool() {
        shutdown();
        for (auto& thread : threads_) {
            if (thread.joinable()) {
                thread.join();
            }
        }
    }

    std::future<void> scheduleTask(std::function<void(const MultimediaFile&)> task, const MultimediaFile& file) {
        auto promise = std::make_shared<std::promise<void>>();
        std::lock_guard<std::mutex> lock(queueMutex_);
        tasks_.emplace([task, file, promise]() {
            task(file);
            promise->set_value();
        });

        condition_.notify_one();
        return promise->get_future();
    }

private:
    void workerFunction() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(queueMutex_);
                condition_.wait(lock, [this](){ return shutdown_ || !tasks_.empty(); });

                if (shutdown_) {
                    break;
                }

                task = std::move(tasks_.front());
                tasks_.pop();
            }

            task();
        }
    }

    void shutdown() {
        std::lock_guard<std::mutex> lock(queueMutex_);
        shutdown_ = true;
        condition_.notify_all();
    }

    bool shutdown_;
    std::vector<std::thread> threads_;
    std::queue<std::function<void()>> tasks_;
    std::condition_variable condition_;
    std::mutex queueMutex_;
};
```
