#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>

template <typename T>
class SafeQueue {
public:
    SafeQueue(void) : q(), m(), cond() {}
    ~SafeQueue(void) {}

    void enqueue(T t) {
        std::lock_guard<std::mutex> lock(m);
        q.push(t);
        cond.notify_one();
    }

    T dequeue(void) {
        std::unique_lock<std::mutex> lock(m);
        while(q.empty()) {
            cond.wait(lock);
        }
        T val = q.front();
        q.pop();
        return val;
    }

private:
    std::queue<T> q;
    mutable std::mutex m;
    std::condition_variable cond;
};
```

This `SafeQueue` class is a thread-safe FIFO queue. It uses `std::unique_lock` to acquire the lock on the condition variable, which allows for more flexibility in waiting and reacquiring the lock at other times than just when it's notified. If the queue is empty, `wait()` will release the lock until it receives a notification through `notify_one()` or `notify_all()`.

