    return NULL;
}

// Function to create a new thread pool
ThreadPool* create_thread_pool(int num_threads) {
    ThreadPool *tp = malloc(sizeof(ThreadPool));  // allocate memory for thread pool
    tp->num_threads = num_threads;  // set number of threads in pool
    tp->threads = malloc(num_threads * sizeof(pthread_t));  // allocate memory for pthread array
    return tp;
}

// Function to submit tasks to thread pool
void submit_task(ThreadPool *tp, char* xml) {
    static int i = 0;

    if (i < tp->num_threads) {  // check if we have available threads in the pool
        pthread_create(&(tp->threads[i]), NULL, processXML, xml);  // create new thread and start it
        i++;
    } else {
