['Here's a basic example of how you might start to implement some of these features in C:

```c
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>

int resolve_hostname(const char* hostname, u_char* ip_address) {
    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET; // Use IPv4
    hints.ai_socktype = SOCK_STREAM; // TCP socket

    struct addrinfo* result = NULL;
    int error = 0;
    if ((error = getaddrinfo(hostname, "http", &hints, &result)) != 0) {
        fprintf(stderr, "%s\n", gai_strerror(error));
        return -1; // Error resolving hostname
    }

    if (result->ai_addrlen > sizeof(struct sockaddr_in)) {
        fprintf(stderr, "IPv4 address is expected but got something else\n");
        freeaddrinfo(result);
        return -1; // Unexpected format of the resolved address
    }

    struct sockaddr_in* addr = (struct sockaddr_in*) result->ai_addr;
    memcpy(ip_address, &addr->sin_addr, sizeof(struct in_addr));

    freeaddrinfo(result); // Free the linked list

    return 0; // Success
}
```
This function takes a hostname and an `u_char` array to store the IP address. It uses the getaddrinfo() function from the C standard library, which performs DNS resolution. If any error occurs during the process or if the resolved address is not in the expected format, appropriate errors are printed and returned.
