```c
#include <pthread.h>
#include <stdio.h>
#include <unistd.h>
#define NUM_THREADS 5

void* worker(void *arg) {
    long id = (long)arg;
    printf("Thread %ld running\n", id);
    sleep(2); // simulate work
    return NULL;
}

int main() {
    pthread_t threads[NUM_THREADS];
    int rc;

    for (long i = 0; i < NUM_THREADS; ++i) {
        printf("Creating thread %ld\n", i);

        // Thread creation
        rc = pthread_create(&threads[i], NULL, worker, (void*)i); 
        if (rc) {
            printf("ERROR; return code from pthread_create() is %d\n", rc);
            return -1;
        }
    }

    for(int i = 0; i < NUM_THREADS; ++i) {
       // Wait for threads to finish
       pthread_join(threads[i], NULL); 
    }

    printf("All threads finished\n");

    return 0;
}
```
This program creates a fixed-size thread pool and assigns tasks one at a time. This is just a starting point, you would need to add more functionality to handle dynamic scaling based on system load, XML parsing, REST API implementation, etc. Note that real-world applications usually require much more than this simple example as it doesn't take into account many aspects like thread safety, memory management, error handling, logging, configuration service integration, distributed cache management, etc.
