        pass 

    def orchestrate(self):
        start = time.time()
        futures = [self.executor.submit(self.fetch_from_source, source) for source in self.data_sources]
        results = []
        for future in concurrent.futures.as_completed(futures):
            try:
                data, transformations = future.result()
                if data is not None: 
                    transformed_data = self.process_data(data) # apply transformations
                    results.append(transformed_data)
            except Exception as exc:
                logging.error('Exception occurred: %s' % (exc))
        end = time.time()

        logging.info("Fetching and processing took {:.2f} seconds".format(end-start))
        return results 
