class ConfigService {
    std::unordered_map<std::string, std::string> config;
public:
    std::string getConfig(const std::string& key) const {
        if (config.find(key) == config.end()) throw std::invalid_argument("Invalid configuration key");
        return config[key];
    }
};

std::mutex mtx;  // global mutex for accessing the list
ConfigService configService;  // external configuration service

void insertAfterFirstOccurrence(std::forward_list<std::string>& flist, const std::string& toInsert, std::string target = "") {
    if (toInsert.empty() || all_of(toInsert.begin(), toInsert.end(), ::isspace))  throw std::invalid_argument("Invalid string to insert");

    mtx.lock();  // lock the list for thread safety

    if (target == "") target = configService.getConfig("defaultTarget");

    auto it = find(flist.begin(), flist.end(), target);
    if (it != flist.end()) {
        flist.insert_after(it, toInsert);
    } else {
        flist.push_front(toInsert);
    }

    mtx.unlock();  // unlock the list
}
```

