char* appendSlash(const char* str, size_t limit) {
    if (strlen(str) > limit) {
        return NULL;
    }

    char* result = malloc(limit + 2); // allow for space and null terminator
    strcpy(result, str);
    strcat(result, "/");

    return result;
}
```
