import com.google.common.cache.LoadingCache;
import org.apache.commons.codec.binary.Base64;
import org.apache.kafka.clients.producer.*;

public class MoSTStateManager {
    private static final String TOPIC = "topic";
    KafkaProducer<String, String> producer = new KafkaProducer<>(props);
    private LoadingCache<String, MoSTState> cache;

    public MoSTStateManager() {
        CacheLoader<String, MoSTState> loader;
        loader = new CacheLoader<>(){ 
            @Override
            public MoSTState load(String key) throws Exception {
                return getFromCloudAndValidate(key);
            }
        };

        cache = CacheBuilder.newBuilder()
                            .maximumSize(10_000) 
                            .expireAfterWrite(2, TimeUnit.MINUTES) 
                            .build(loader); 
    }

    private MoSTState getFromCloudAndValidate(String key){
        String base64 = fetchFromCloudStorageService(key); // Assume it can throw Exceptions for corrupted data and network latency issues.
        byte[] bytes = Base64.decodeBase64(base64);

        try{
            ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
            ObjectInputStream in = new ObjectInputStream(bais);
            MoSTState state = (MoSTState) in.readObject();
            return state;
        } catch(Exception e){ // Catch deserialization error.
            throw new RuntimeException("Deserialization error", e);
        }
    }

    public MoSTState getState(String key){
        try{
            return cache.get(key);
        }catch(Exception e){ 
            // Log the exception and retry, with exponential backoff strategy.
            Thread.sleep((long) Math.pow(2, retryCount));
            ++retryCount;
            if(retryCount > 10){
                throw new RuntimeException("Failed after many retries", e);
            }
        }
    }

    public void updateState(MoSTState state){ 
        // Assume there's a way to identify the key. 
        String key = getKeyFromState(state);

        producer.send(new ProducerRecord<>(TOPIC, key, state));
        cache.put(key, state);
    }

