int main() {
    long num_sessions = 1000000; // Assume 1M sessions for testing purposes
    SessionRecord* session_records = NULL;

    if (initRecords(num_sessions, &session_records) != 0) {
        fprintf(stderr, "Failed to initialize records\n");
        return EXIT_FAILURE;
    }

    // Start the background pruning task
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, &pruneExpiredSessions, session_records) != 0) {
        fprintf(stderr, "Failed to create pruning thread\n");
        return EXIT_FAILURE;
    }

    // Validate sessions in a loop
    for (long i = 0; i < num_sessions; i++) {
        if (validateSession(session_records[i]) != 0) {
            handleNetworkError();
            break; // If network error occurs, stop validating
        }
    }

    pthread_join(thread_id, NULL); // Wait for the thread to finish
    free(session_records);
}
