use async_std::task;
use reqwest::Client;
use std::sync::Arc;
use std::time::Duration;
use futures::future::{try_join, Either, pending};

async fn make_request(client: &Client, url: &str) -> Result<(), Box<dyn std::error::Error>> {
    client.get(url).send().await?;
    Ok(())
}

#[task::main]
async fn main() {
    let config_service = "http://config-service";
    let analytics_api = "http://analytics-api";
    let notification_service = "http://notification-service";

    let client = Client::builder().timeout(Duration::from_secs(5)).build()?;

    let config_future = make_request(&client, &config_service);
    let analytics_future = make_request(&client, &analytics_api);
    let notification_future = make_request(&client, &notification_service);

    match try_join(config_future.fuse(), analytics_future.fuse(), notification_future.fuse()).await {
        Either::Left(_) => panicln_and_stop("Config service failed"),
        Either::Right(Either::Left(_)) => panicln_and_stop("Analytics API failed"),
        Either::Right(Either::Right(_)) => panicln_and_stop("Notification service failed"),
    };
}
```

