            if (code !== 0) {
                logger.error(`Command execution failed with exit code: ${code}. Command: ${command}`);
                reject(new Error(`Command execution failed: ${command}`));
            } else {
                logger.info(`Successfully executed command: ${command}`);
                resolve(output);
            }
        });
    });
}
