['Below is an example solution using .NET 5, Newtonsoft Json.NET for JSON serialization/deserialization, HttpClient for making HTTP requests, and System.Threading.Tasks for asynchronous programming:

```csharp
using System;
using System.Net.Http;
using System.Text;
using System.Collections.Generic;
using Newtonsoft.Json;
using System.Linq;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

public class DataProcessor
{
    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _cache;
    private const string ApiBaseUrl = "https://api.example.com"; // replace with actual API base URL

    public DataProcessor(HttpClient httpClient, IMemoryCache cache)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _cache = cache ?? throw new ArgumentNullException(nameof(cache));
    }

    public async Task<IEnumerable<string>> ProcessAndTrimDataAsync(string identifier, int maxSize)
    {
        // Fetch the binary data from the external API using HTTP GET requests
        var response = await _httpClient.GetByteArrayAsync($"{ApiBaseUrl}/{identifier}");

        // Deserialize the binary data into the custom data structure
        IEnumerable<string> collection;

        try
        {
            string json = Encoding.UTF8.GetString(response);
            collection = JsonConvert.DeserializeObject<IEnumerable<string>>(json);
        }
        catch (JsonReaderException ex)
        {
            // Log the exception and return an empty collection
            Console.WriteLine($"Failed to deserialize data: {ex}");
            return Enumerable.Empty<string>();
        }

        // Iterate through the collection, trimming each string
        var result = new List<string>();

        foreach (var item in collection)
        {
            if (item.Length > maxSize)
                continue;

            var trimmedItem = item.Substring(0, Math.Min(maxSize, item.Length));
            if (trimmedItem.Length < item.Length) 
                trimmedItem += "/"; // Append a forward slash to the end of the string

            result.Add(trimmedItem);
        }

        return result;
    }
}
```

For testing, you can use xUnit and Moq libraries for unit tests (to test deserialization) and HttpClientFactory library for integration tests (for API interactions).

To handle concurrent requests efficiently without causing race conditions, consider using the `ConcurrentDictionary` or `ReaderWriterLockSlim` classes. 

