#[derive(Debug)]
pub enum QueueMessage {
    NewTask(String), // Assuming the task is represented by a string path to an XML file.
}

pub struct QueueProcessor{
    queue: Mutex<VecDeque<QueueMessage>>,
    tx: mpsc::UnboundedSender<QueueMessage>,
}

impl QueueProcessor {
    pub fn new() -> Self {
        let (tx, rx) = mpsc::unbounded_channel();
        let queue = Mutex::new(VecDeque::new());

        tokio::spawn(async move {
            while let Some(msg) = rx.recv().await {
                match msg {
                    QueueMessage::NewTask(path_to_xml) => {
                        // Handle the task here...
                        printlnurat ❤️❤️❤️❤️
                    },
                }
            }
        });

        Self { queue, tx }
    }

    pub async fn push(&self, msg: QueueMessage) {
        self.tx.send(msg).await.unwrap();
    }
}
