#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record record;
    struct Node *parent;
    int rank;
} Node;

Node* makeSet(Record record) {
    Node* node = malloc(sizeof(Node));
    node->record = record;
    node->parent = NULL;
    node->rank = 0;
    return node;
}

Node* find(Node *node) {
    if (node->parent != NULL) 
        node->parent = find(node->parent);
    return node->parent == NULL ? node : node->parent;
}

void unionSet(Node *node1, Node *node2) {
    node1 = find(node1);
    node2 = find(node2);

    if (node1 != node2) {
        if (node1->rank < node2->rank) 
            node1->parent = node2;
        else if (node1->rank > node2->rank) 
            node2->parent = node1;
        else {
            node2->parent = node1;
            node1->rank++;
        }
    }
}

typedef struct Collection {
    Node **nodes; // Array of pointers to Nodes
    pthread_mutex_t lock;
    int size;
    long totalOffset;
    clock_t lastUpdateTime;
} Collection;

void initCollection(Collection *collection, int maxSize) {
    collection->nodes = malloc(sizeof(Node*) * maxSize);
    for (int i = 0; i < maxSize; ++i) 
        collection->nodes[i] = NULL;
    pthread_mutex_init(&collection->lock, NULL);
    collection->size = 0;
    collection->totalOffset = 0;
}

void destroyCollection(Collection *collection) {
    for (int i = 0; i < collection->size; ++i) 
        free(collection->nodes[i]);
    free(collection->nodes);
    pthread_mutex_destroy(&collection->lock);
}

void addRecord(Collection *collection, Record record) {
    Node *node = makeSet(record);

    pthread_mutex_lock(&collection->lock);
    collection->nodes[collection->size++] = node;
    collection->totalOffset += node->record.offset;
    pthread_mutex_unlock(&collection->lock);
}

void removeRecord(Collection *collection, int key) {
    pthread_mutex_lock(&collection->lock);

    for (int i = 0; i < collection->size; ++i) {
        if (collection->nodes[i]->record.key == key) {
            free(collection->nodes[i]);

            // Move last node to this position, and decrement size
            collection->nodes[i] = collection->nodes[--collection->size];
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void updateOffset(Collection *collection, int key, long newOffset) {
    pthread_mutex_lock(&collection->lock);

    for (int i = 0; i < collection->size; ++i) {
        if (collection->nodes[i]->record.key == key) {
            collection->totalOffset -= collection->nodes[i]->record.offset;
            collection->nodes[i]->record.offset = newOffset;
            collection->totalOffset += newOffset;
            break;
        }
    }

    pthread_mutex_unlock(&collection->lock);
}

void updateExternalSource(Collection *collection) {
