class LockManager {
private:
    std::map<std::string, std::mutex> locks;
public:
    void AcquireLock(const std::string &lock_name) {
        if (locks.find(lock_name) == locks.end()) {
            locks[lock_name] = std::mutex(); // create a new lock
        }
        locks[lock_name].lock(); // acquire the lock
    }

    void ReleaseLock(const std::string &lock_name) {
        auto it = locks.find(lock_name);
        if (it != locks.end()) {
            it->second.unlock(); // release the lock
        } else {
            throw std::runtime_error("No such lock");
        }
    }
};
