['Here is a high-level pseudo code implementation for the configuration management tool based on your requirements. This will be a very simplified version of a configuration management system that you may need to expand upon with additional features according to specific project needs.

```python
import json
from concurrent.futures import ThreadPoolExecutor
import requests
from cryptography.fernet import Fernet

class ConfigManager:
    def __init__(self, config_path):
        self.config = {}  # Assume a dictionary for configuration
        self.key_manager = KeyManager()  # Your Key Manager Class
        self.load_config(config_path)

    def load_config(self, path):
        try:
            with open(path, 'r') as file:
                config = json.loads(file.read())
                for key in config:
                    if "encrypted" in config[key]:
                        config[key]["value"] = self.key_manager.decrypt(config[key]["value"])
                self.config = config
        except Exception as e:
            print("Error loading configuration file ", str(e))  # Better error logging here

    def save_config(self, path):
        try:
            with open(path, 'w') as file:
                encrypted_config = self.config.copy()
                for key in encrypted_config:
                    if "encrypted" in encrypted_config[key]:
                        encrypted_config[key]["value"] = self.key_manager.encrypt(encrypted_config[key]["value"])
                file.write(json.dumps(encrypted_config))
        except Exception as e:
            print("Error saving configuration file ", str(e))  # Better error logging here

    def fetch_external_settings(self):
        external_services = self.config["external_services"]
        with ThreadPoolExecutor(max_workers=5) as executor:
            for service in external_services:
                executor.submit(self._fetch, service)

    def _fetch(self, service):
        try:
            response = requests.get(service["url"], timeout=5)
            if response.status_code == 200:
                self.config[service["name"]]["value"] = json.loads(response.text)
        except Exception as e:
            print("Failed to fetch service ", service, " due to error -> ", str(e))  # Better error logging here

class KeyManager:
    def __init__(self):
        self.key = Fernet.generate_key()  # Generate key for encryption/decryption
        self.cipher_suite = Fernet(self.key)

    def encrypt(self, message):
        return self.cipher_suite.encrypt(message.encode()).decode()  # Encrypt a string

    def decrypt(self, cipher_text):
        return self.cipher_suite.decrypt(cipher_text.encode()).decode()  # Decrypt a cipher text
```
The above pseudo-code shows how to load and save configuration files, manage encryption of sensitive values, fetch external services' settings and manage keys. However, it is important to note that this code needs to be expanded upon in order to include error handling and logging as well as user-friendly interface for managing configurations. Moreover, security measures like role-based access control (RBAC) for accessing configuration files are not included which must be carefully considered according to the project's requirements.
']

