extern crate failure; // error handling
use futures::{Future, Stream};
use tokio::executor::current_thread::Handle;
use tokio::net::TcpStream;
use tokio::prelude::*;

pub struct Queue {
    tasks: Vec<Task>,
}

impl Queue {
    pub fn new() -> Self {
        Queue { tasks: vec![], }
    }

    // Add a task to the queue.
    pub fn add_task(&mut self, task: Task) {
        self.tasks.push(task);
    }

    // Process all tasks in the queue concurrently.
    pub fn process(&self) -> impl Future<Item = (), Error = failure::Error> + Send {
        let handles = self.tasks.iter().map(|task| task.process()).collect();

        tokio::spawn(async move {
            futures::future::join_all(handles)
                .await
                .map_err(failure::Error::from_boxed_compat);
        });
    }
}

pub struct Task {
    file: File, // Struct representing a file to be processed.
}

impl Task {
