```C++
#include <iostream>
#include <queue>
#include <map>
#include <thread>
#include <asio.hpp>

using asio::ip::tcp;

class WebSocketClient {
public:
    WebSocketClient(const std::string& host, const std::string& port)
        : socket_(io_context_) 
    {
        tcp::resolver resolver(io_context_);
        asio::connect(socket_, resolver.resolve(host, port));
    }
    ~WebSocketClient() {
        if (worker_.joinable()) worker_.join();
        socket_.close();
    }

    void Start() {
        worker_ = std::thread(&WebSocketClient::Run, this);
    }

private:
    void Run() {
        while(true) {  // In a real-world application, you should have proper stop condition.
            asio::error_code error;
            asio::read(socket_, asio::dynamic_buffer(data), error);
            if (error == asio::error::eof) break; // Connection closed cleanly by peer.
        }
    }

    asio::streambuf data;
    std::thread worker_;
    asio::io_context io_context_;
    tcp::socket socket_;
};

class TransactionQueue {
public:
    void Submit(std::string transaction) {
        queue_.push(transaction);
    }

    std::string Fetch() {
        if (queue_.empty()) return "";
        std::string result = queue_.front();
        queue_.pop();
        return result;
    }

private:
    std::queue<std::string> queue_;
};

void UpdateMap(std::map<std::string, int>& data, const std::string& key, int value) {
    auto iter = data.find(key);
    if (iter == data.end()) {
        data[key] = value;
    } else {
        iter->second += value;
    }
}
```
