    public WebhookProcessorService(int maxConcurrentThreads) {
        this.executor = Executors.newFixedThreadPool(maxConcurrentThreads);
        this.webhookQueue = new PriorityBlockingQueue<>();

        for (int i = 0; i < maxConcurrentThreads; i++) {
            executor.submit(() -> processWebhooks());
        }
