const fs = require('fs');
const path = require('path');
const express = require('express');
const fetch = require('node-fetch');
const app = express();

app.use(express.json());

let deduplicationCache = new Set(); // for storing seen files' metadata and content

function readFile(filePath) {
    return fs.promises.readFile(filePath, 'utf8')
        .then((data) => data)
}

async function processFilesInDirectory(directoryPath, criteriaFn) {
    const files = await fs.promises.readdir(directoryPath);

    for (const file of files) {
        const filePath = path.join(directoryPath, file);
        const content = await readFile(filePath);
        const metadata = await fs.promises.stat(filePath);

        if (!deduplicationCache.has(metadata + content)) { // check for deduplication
            deduplicationCache.add(metadata + content);

            if (criteriaFn(content, metadata)) { // filter using user-defined criteria
                let response = await fetch('http://externalServiceUrl', {method: 'POST', body: JSON.stringify({content})});
                response = await response.json();

                console.log(response); // handle the result accordingly
            }
        }
    }
}

app.post('/startProcessing', (req, res) => {
    let directoryPath = req.body.directoryPath;

    try {
        processFilesInDirectory(directoryPath, req.body.criteriaFn); // user-defined criteria function here
        res.send('Processing started');
    } catch (err) {
        console.error(`Error occurred during processing: ${err}`); 
        res.status(500).send('An error occurred during processing');
    }
});
```

This is a basic example and does not include all the aspects you mentioned like real-time monitoring, OAuth2.0, detailed performance profiling reports etc. For these features, you might want to consider using libraries such as `socket.io` for real-time communication, `jsonwebtoken` and `express-jwt` for OAuth 2.0, and `node-summary` or `clinic` for detailed performance profiling reports respectively.

