import java.util.concurrent.*;
import org.apache.commons.dbcp2.*;

public class TransactionService {
    private final BlockingQueue<Transaction> queue;
    private final BasicDataSource dataSource;
    private final ExecutorService executor;

    public TransactionService() {
        this.queue = new LinkedBlockingQueue<>();

        // Initialize connection pool to external transaction database
        this.dataSource = new BasicDataSource();
        dataSource.setDriverClassName("com.mysql.jdbc.Driver");
        dataSource.setUrl("jdbc:mysql://localhost/transactionsDB");
        dataSource.setUsername("username");
        dataSource.setPassword("password");

        // Initialize thread pool for async processing
        this.executor = Executors.newFixedThreadPool(10);
    }

    public void processTransaction(final Transaction transaction) {
        try {
            // Add to queue and handle potential backpressure
            if (!queue.offer(transaction, 5, TimeUnit.SECONDS)) {
                System.err.println("Dropping transaction due to high load");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        // Asynchronous processing
        executor.execute(() -> {
            try {
                Transaction t = queue.take();  // Will block if no elements are available

                // Apply complex filtering criteria and weighted sum calculation
                // For brevity, the actual implementation is omitted here

                // Save to database
                Connection conn = dataSource.getConnection();
                PreparedStatement statement = conn.prepareStatement("INSERT INTO transactions(id, amount) VALUES (?, ?)");
                statement.setInt(1, t.getId());
                statement.setDouble(2, t.getAmount());

                int rowsInserted = statement.executeUpdate();
                if (rowsInserted > 0) {
                    System.out.println("Transaction processed and saved to database");
                }
            } catch (SQLException | InterruptedException e) {
                // Log error, but don't crash
                e.printStackTrace();
            } 
        });
    }

    public void adjustThreshold(int threshold) {
        // Dynamically tune the threshold for transaction retention based on current system load
    }
}
```
