// Assuming your records are like this:
typedef struct Record {
    long offset;
    int key;
    char* user_identifier;
} Record;

void* parseJson(char* jsonFilePath, size_t maxOffsetSize, size_t maxKeySize) {
  // Thread safety is ensured here by using a mutex.
  static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

  cJSON *json = NULL;
  FILE* fp = NULL;
  Record* records = malloc(maxOffsetSize * maxKeySize * sizeof(Record));
  if (records == NULL) {
    printf("Failed to allocate memory\n");
    return NULL;
  }

  // Lock the critical section while we are reading and parsing the JSON file.
  pthread_mutex_lock(&lock);

  fp = fopen(jsonFilePath, "r");
  if (fp == NULL) {
    printf("Failed to open the json file\n");
    goto cleanup; // jump to label 'cleanup'
  }

  char buffer[65536];
  fread(buffer, 1, sizeof(buffer), fp);

  if (ferror(fp)) {
    printf("Failed to read the file\n");
    goto cleanup; // jump to label 'cleanup'
  }

  json = cJSON_Parse(buffer);
  if (json == NULL) {
    const char *error_ptr = cJSON_GetErrorPtr();
    if (error_ptr != NULL) {
      printf("Failed to parse JSON file: %s\n", error_ptr);
    } else {
      printf("Unknown error parsing the json\n");
    }
  }

  // Parse the json and fill your records here...

cleanup:
  if (fp != NULL) fclose(fp);
  if (json != NULL) cJSON_Delete(json);
  pthread_mutex_unlock(&lock); // Unlock the critical section.

  return records;
}
```
