["Below is a basic code skeleton of how you might approach this problem in Node.js. This is not a complete solution but rather an outline for you to start from. 

```javascript
const express = require('express');
const bodyParser = require('body-parser');
const kafkaNode = require('kafka-node');
const opentracing = require('opentracing');
const { initTracerFromEnv } = require('jaeger-client');

// Initialize the tracer 
let config = {
  serviceName: 'notification-service',
};
let tracer = initTracerFromEnv(config);

// initialize express server
const app = express();
app.use(bodyParser.json());

// Create Kafka client and producer/consumer
let kafkaClientOptions = {sessionTimeout: 100, spinDelay: 100, retries: 2};
let kafkaClient = new kafkaNode.KafkaClient(kafkaClientOptions);
let producer = new kafkaNode.HighLevelProducer(kafkaClient);
producer.on('error', function (err) {
    console.log('Error from Kafka: ', err);
});

// List of notification providers
const providers = [
  'firebase-provider',
  'apple-provider',
  'onesignal-provider'
];
let currentProvider = 0;

app.post('/sendNotification', async (req, res) => {
  let span = tracer.startSpan('send_notification');
  // Set the context for the new span
  let headers = {};
  tracer.inject(span.context(), opentracing.FORMAT_HTTP_HEADERS, headers);

  const payloads = [{ topic: 'test', messages: JSON.stringify(req.body) }];

  // Try to send notification through current provider 
  try {
    await producer.sendAsync(payloads[0], req.body.partition, req.body.messageAttributes);
    span.finish();
    res.status(200).json({ message: 'Notification sent successfully.' });
  } catch (err) {
    // If sending notification fails through current provider, switch to the next one and retry
    console.error(`Error while sending notification using ${providers[currentProvider]}`, err);
    span.finish();
    currentProvider = (currentProvider + 1) % providers.length;
    try {
      await producer.sendAsync(payloads[0], req.body.partition, req.body.messageAttributes);
      res.status(200).json({ message: 'Notification sent successfully.' });
    } catch (err) {
      console.error('Failed to send notification', err);
      // If all providers fail, return an error response
      res.status(500).json({ message: 'Failed to send notification.' });
    }
  }
});

app.listen(3000, () => console.log('Notification service listening on port 3000'));
```
This is a very high-level code and it's not production-ready. You need to handle things like user consent management, data anonymization, fallback strategies, backpressure mechanisms etc. Also you might want to consider using dedicated microservices frameworks or libraries for Node.js such as NestJS or Micro in order to structure your code better and make it more maintainable.
"]

