Implementation of the above header file might look like this:

```c
// File: nicb_manager.c
#include "nicb_manager.h"
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct Nicb {
    char* mac_address;
    char* ip_config;
    unsigned short port;
} Nicb;

struct NicbManager {
    pthread_mutex_t lock;
    Nicb** nicbs;
    int count;
};

NicbManager* create_nicb_manager() {
    NicbManager* manager = (NicbManager*)malloc(sizeof(NicbManager));
    pthread_mutex_init(&manager->lock, NULL);
    manager->count = 0;
    manager->nicbs = NULL;
    return manager;
}

void destroy_nicb_manager(NicbManager* manager) {
    for (int i = 0; i < manager->count; ++i) {
        free(manager->nicbs[i]->mac_address);
        free(manager->nicbs[i]->ip_config);
        free(manager->nicbs[i]);
    }
    if (manager->nicbs != NULL) {
        free(manager->nicbs);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

bool add_nicb(NicbManager* manager, const char* mac_address, const char* ip_config, unsigned short port) {
    pthread_mutex_lock(&manager->lock);

    Nicb* nicb = (Nicb*)malloc(sizeof(Nicb));
    nicb->mac_address = strdup(mac_address);
    nicb->ip_config = strdup(ip_config);
    nicb->port = port;

    manager->nicbs = realloc(manager->nicbs, sizeof(Nicb*) * (manager->count + 1));
    manager->nicbs[manager->count] = nicb;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return true;
}
```

This is a very basic example. In reality, you would have to handle error conditions (e.g., `malloc` returning NULL, etc.), possibly make your code thread-safe, manage memory better, and consider things like performance optimization. Also, the architecture of this library should be designed according to the constraints given in the problem statement.
']

