['Here is a simplified example of how you could structure your library using C. This code does not cover all the mentioned constraints, but it gives an idea on how to start building such a library. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <curl/curl.h>  // For network operations using cURL

// Structure for the configuration of a cell
typedef struct {
    int frequencyBand;
    int bandwidth;
    int cellIdentity;
} CellConfig;

// Structure to hold data for each cell configuration
typedef struct CellNode {
    CellConfig* config;
    struct CellNode *next;  // Link for linked list
} CellNode;

// Global Variables
CellNode *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Add a cell configuration to the pool
void addCellConfig(CellConfig* config) {
    pthread_mutex_lock(&lock);

    CellNode *newNode = (CellNode*)malloc(sizeof(CellNode));
    newNode->config = config;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

// Remove a cell configuration from the pool
void removeCellConfig(int cellIdentity) {
    pthread_mutex_lock(&lock);

    CellNode *temp = head, *prev = NULL;

    // If the cell is found in the head node itself
    if (temp != NULL && temp->config->cellIdentity == cellIdentity) {
        head = temp->next;
        free(temp);
        pthread_mutex_unlock(&lock);
        return;
    }

    // Else search the node and remove it from linked list
    while (temp != NULL && temp->config->cellIdentity != cellIdentity) {
        prev = temp;
        temp = temp->next;
    }

    if(temp == NULL){
      pthread_mutex_unlock(&lock);
      return;  // Cell not found in the list
    }
    prev->next = temp->next;
    free(temp);

    pthread_mutex_unlock(&lock);
}

// Update a cell configuration from the RESTful API
void updateCellConfigFromAPI(int cellIdentity) {
    // Use libcurl to send an HTTP request and parse response
    CURL *curl;
    CURLcode res;
    curl = curl_easy_init();

