import xml.etree.ElementTree as ET
from xml.dom import minidom
import requests
import threading
import time
import json
from Crypto.Cipher import AES
from kubernetes import client, config

# Load Kube Config
config.load_kube_config()
api = client.CoreV1Api()

class XmlConfig:
    def __init__(self):
        self.lock = threading.Lock()
        self.cipher = AES.new('This is a key123', AES.MODE_CBC, 'This is an IV456')

    def parse_and_replace(self, xmlfile, replacements):
        try:
            tree = ET.parse(xmlfile)
            root = tree.getroot()

            for key in replacements:
                for elem in root.iter():
                    if key in elem.text:
                        elem.text = elem.text.replace(key, replacements[key])

            self.save_xml(tree)
        except ET.ParseError as e:
            print("Parsing Error: ", str(e))

    def save_xml(self, tree):
        xmlstr = minidom.parseString(ET.tostring(tree.getroot())).toprettyxml(indent="   ")
        with self.lock:
            with open("modified.xml", "w") as f:
                f.write(self.__encrypt__(xmlstr))

    def __encrypt__(self, data):
        return self.cipher.encrypt(data)

class ApiHandler:
    def __init__(self):
        pass

    def make_request(self, url, retries=3):
        for i in range(retries):
            try:
                response = requests.get(url)
                return json.loads(response.content)
            except (requests.exceptions.RequestException, ValueError) as e:
                print("Failed to get data from API.", str(e))
                time.sleep(2 ** i)  # Exponential backoff
        return {}

class AdminUI:
