```cpp
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>
#include "json.hpp" // include nlohmann::json for JSON parsing
#include "curl/curl.h"
// Other required headers and namespaces...

class JsonQueue {
public:
    void push(nlohmann::json data);
    bool pop(nlohmann::json &data);
private:
    std::queue<nlohmann::json> queue_;
    std::mutex mutex_;
    std::condition_variable conditionVariable_;
};

void JsonQueue::push(nlohmann::json data) {
    std::lock_guard<std::mutex> lock(mutex_);
    queue_.push(data);
    conditionVariable_.notify_all();
}

bool JsonQueue::pop(nlohmann::json &data) {
    std::unique_lock<std::mutex> lock(mutex_);
    while (queue_.empty()) {
        if (conditionVariable_.wait_for(lock, std::chrono::seconds(1)) == std::cv_status::timeout) 
            return false; // timeout after 1 second
    }
    data = queue_.front();
    queue_.pop();
    return true;
}
```
The above class provides thread-safe access to the JSON documents queue.

To handle asynchronous task submission and result retrieval, you can use C++ std::future/std::promise or boost::future/boost::promise.

