std::mutex mtx;
std::forward_list<std::string> list;

void insertAfterFirstOccurrence(const std::string& target, const std::string& str) {
    int retryCount = 0;
    while (true) {
        try {
            ConfigurationService service;
            std::string config = service.fetchConfiguration();

            mtx.lock(); // Acquire lock

            auto it = list.begin();
            for (; it != list.end(); ++it) {
                if (*it == target) {
                    break;
                }
            }

            if (it != list.end()) {
                ++it; // Move to next element since we want to insert after the first occurrence of target
            }

            list.insert_after(it, config + str);

            mtx.unlock(); // Release lock
            return;
        } catch (const std::exception& e) {
            if (retryCount > 10) throw;

            ++retryCount;
            unsigned seed = std::chrono::system_clock::now().time_since_epoch().count();
            std::default_random_engine generator(seed);
            std::uniform_int_distribution<int> distribution(0,1<<retryCount); // Exponential backoff with jitter

            int sleepTime = distribution(generator);
            std::this_thread::sleep_for(std::chrono::milliseconds(sleepTime)); // Sleep for some time before retrying.
        }
    } 
}
```

