    public async Task ParseAndFetchAsync(string xmlPath, string namespaceUri, string tagName)
    {
        using var reader = XmlReader.Create(xmlPath);

        while (await reader.ReadAsync())
        {
            if (reader.NodeType == XmlNodeType.Element && reader.NamespaceURI == namespaceUri && reader.LocalName == tagName)
            {
                await FetchMetadataAsync(reader["id"]); // assumes "id" is the unique identifier for each element
            }
        }
    }

    private async Task<bool> FetchMetadataAsync(string id)
