```python
import asyncio
from payment_gateways import PaymentGateway1Adapter, PaymentGateway2Adapter, ...

class Transaction:
    def __init__(self):
        self._gateway = None  # Instantiate respective gateway adapter based on transaction type.

    @asyncio.coroutine
    def process(self):
        yield from asyncio.sleep(0)  # Yield control to other tasks, mimicking non-blocking IO.
        self._gateway.process_transaction()

class PaymentGatewayHandler:
    def __init__(self, max_concurrent_tasks):
        self.semaphore = asyncio.Semaphore(max_concurrent_tasks)

    @asyncio.coroutine
    def handle_transaction(self, transaction):
        with (yield from self.semaphore):  # Limit the number of concurrent tasks using a semaphore.
            yield from transaction.process()

def main():
    transactions = [Transaction() for _ in range(10000)]  # Generate 10,000 transactions.

    handler = PaymentGatewayHandler(max_concurrent_tasks=250)
    loop = asyncio.get_event_loop()
    tasks = [handler.handle_transaction(trxn) for trxn in transactions]  # Generate task list for each transaction.

    try:
        loop.run_until_complete(asyncio.wait(tasks))  # Run all tasks concurrently.
    finally:
        loop.close()

if __name__ == '__main__':
    main()
```

This code uses Python's `asyncio` library to asynchronously process transactions, limiting the number of concurrent tasks to prevent blocking and ensuring a latency under 200 milliseconds. It instantiates an adapter based on the type of transaction, allowing for seamless integration with various payment gateways.
"]

