// build_system/src/resource.rs
use std::sync::{Arc, RwLock};
use std::thread;

pub struct ResourceManager {
    resources: Arc<RwLock<Resource>>,
}

impl ResourceManager {
    pub fn new() -> Self {
        Self {
            resources: Arc::new(RwLock::new(Resource { available_resources: 10 })),
        }
    }

    pub fn use_resource(&self) -> Option<Arc<RwLock<Resource>>> {
        let locked = self.resources.read().unwrap();
        if locked.available_resources > 0 {
            let mut writable = self.resources.write().unwrap();
            writable.available_resources -= 1;
            Some(Arc::clone(&self.resources))
        } else {
            None
        }
    }
}
```

