Here's an example of how you might create a simple FIFO queue in C:

```c
#include <stdlib.h>
#define SIZE 500

typedef struct {
    int items[SIZE];
    int front;
    int rear;
} Queue;

Queue* createQueue() {
    Queue* q = malloc(sizeof(Queue));
    q->front = -1;
    q->rear = -1;
    return q;
}

int isFull(Queue* q) {
    if((q->rear == SIZE - 1 && q->front == 0) || (q->front == q->rear + 1)) {
        return 1;
    }
    return 0;
}

int isEmpty(Queue* q) {
    if(q->front == -1) {
        return 1;
    }
    return 0;
}

void enqueue(Queue* q, int value) {
    if(isFull(q)) {
        printf("Queue is full\n");
    } else {
        if(q->front == -1) {
            q->front = 0;
        }
        q->rear = (q->rear + 1) % SIZE;
        q->items[q->rear] = value;
    }
}

int dequeue(Queue* q) {
    int item;
    if(isEmpty(q)) {
        printf("Queue is empty\n");
        item = -1;
    } else {
        item = q->items[q->front];
        if(q->front == q->rear) {
            q->front = -1;
            q->rear = -1;
        } 
        else {
            q->front = (q->front + 1) % SIZE;
        }
    }
    return item;
}
```
In the above code, we create a simple queue data structure and some basic functions for checking if the queue is full or empty, adding elements to the rear of the queue, and removing elements from the front of the queue.
']

