import asyncio
from abc import ABC, abstractmethod
from typing import List

class AbstractCDNService(ABC):
    @abstractmethod
    def fetch_content(self, url: str) -> bytes:
        pass

class CDNService(AbstractCDNService):
    def __init__(self, cdn_services: List[AbstractCDNService]):
        self.cdn_services = cdn_services

    async def fetch_content(self, url: str) -> bytes:
        for service in self.cdn_services:
            try:
