        salt = encrypted_data['salt']
        key = PBKDF2(password, salt, 32, count=1000000)
        cipher = AES.new(key, AES.MODE_CBC, IV=encrypted_data['iv'])
        return cipher.decrypt(encrypted_data['ciphertext'])

