["Creating a complete C library implementing these features is quite complex and would require significant effort. Here's an outline of how you could start:

```c
#include <stdlib.h>
#include <pthread.h>
#include <libxml/parser.h>

typedef struct task {
    void *data; // XML data
    int (*process)(void *); // Process function
} Task;

typedef struct queue_node {
    Task *task;
    struct queue_node *next;
} QueueNode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
QueueNode *head = NULL, *tail = NULL;

void add_to_queue(Task *task) {
    pthread_mutex_lock(&lock);

    QueueNode *new_node = malloc(sizeof(QueueNode));
    new_node->task = task;
    new_node->next = NULL;

    if (head == NULL) {
        head = new_node;
        tail = new_node;
    } else {
        tail->next = new_node;
        tail = new_node;
    }

    pthread_mutex_unlock(&lock);
}

Task *get_from_queue() {
    Task *task = NULL;
    QueueNode *node;

    pthread_mutex_lock(&lock);

    if (head != NULL) {
        node = head;
        task = node->task;

        head = head->next;
        free(node);

        if (head == NULL) tail = NULL;
    }

    pthread_mutex_unlock(&lock);

    return task;
}

void *process_task(void *arg) {
    Task *task = arg;
    task->process(task->data); // Call the process function with data.
    free(task->data);
    free(task);
    return NULL;
}
```
In this code, `Task` is a struct that holds an XML file and a function pointer to process it. The library maintains a thread-safe queue of tasks which are processed by worker threads in parallel. 

