        _httpClient = new HttpClient { BaseAddress = new Uri(configuration["ExternalAPI:Url"]) };
        _httpClient.DefaultRequestHeaders.Authorization = 
            new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", configuration["ExternalAPI:Token"]);

        var redisConnectionString = configuration["RedisCache:ConnectionString"];
        var connectionMultiplexer = ConnectionMultiplexer.Connect(redisConnectionString);
        _cache = new ConcurrentDictionary<string, (DateTimeOffset, object)>();
    }

    public async Task ProcessAndTrimDataAsync(string identifier, int maxSizeLimit)
    {
        var policy = Policy
            .Handle<HttpRequestException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        var binaryData = await policy.ExecuteAsync(async () => {
            var response = await _httpClient.GetAsync(identifier);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsByteArrayAsync();
        });

        try
        {
            await _semaphore.WaitAsync(); // lock before accessing shared resource (_cache)

            if (!_cache.TryGetValue(identifier, out var cacheEntry)) 
                _cache[identifier] = (DateTimeOffset.UtcNow, JsonConvert.DeserializeObject<CustomDataStructure>(Encoding.UTF8.GetString(binaryData)));

            CustomDataStructure data = ((CustomDataStructure)_cache[identifier].Item2).Clone();

            await _semaphore.Release(); // unlock after accessing shared resource (_cache)

            foreach (var item in data.CollectionOfStringsAndIntegers) 
                if (item is string str && str.Length > maxSizeLimit) 
                    item = str[..maxSizeLimit] + "/";
        }
        catch(JsonSerializationException ex)
        {
            Log.Logger.Error("Failed to deserialize binary data into custom data structure: {@exception}", ex);
        }
    }

    // Remaining code omitted for brevity
}
