class PoolManager {
private:
    std::vector<Pipeline> pipelinePool;
    std::mutex mtx; // Use mutex for thread safety

public:
    void addToPool(const Pipeline& pipeline) {
        const std::lock_guard<std::mutex> lock(mtx); // Ensure atomicity
        pipelinePool.push_back(pipeline);
    }

    Pipeline getFromPool() {
        const std::lock_guard<std::mutex> lock(mtx); // Ensure atomicity
        if (pipelinePool.empty()) throw "Pool is empty";

        auto pipeline = pipelinePool.back();
        pipelinePool.pop_back();
        return pipeline;
    }
};

// Thread-safe queue for priority management
class PriorityQueue {
private:
    std::vector<Pipeline> queue;
    std::mutex mtx; // Use mutex for thread safety

public:
    void addToQueue(const Pipeline& pipeline) {
        const std::lock_guard<std::mutex> lock(mtx); // Ensure atomicity
        queue.push_back(pipeline);

        // Implement logic to sort based on priority
    }

    Pipeline getFromQueue() {
        const std::lock_guard<std::mutex> lock(mtx); // Ensure atomicity
        if (queue.empty()) throw "Queue is empty";

        auto pipeline = queue.front();
        queue.erase(queue.begin());
        return pipeline;
    }
};

