class MediaPipelineManager {
private:
    std::mutex mtx; // Protects access to the queue and sessions vector
    std::queue<Session> sessionQueue;
    std::vector<std::thread> workerThreads;
    int maxSessions = 10000;

public:
    MediaPipelineManager(int numWorkers = std::thread::hardware_concurrency()) {
        // Initialize the thread pool with a fixed number of workers
        for (int i = 0; i < numWorkers; ++i) {
            workerThreads.push_back(std::thread(&MediaPipelineManager::worker, this));
        }
    }

    ~MediaPipelineManager() {
        // Clean up the thread pool when the manager is destroyed
        for (auto& t : workerThreads) {
            if (t.joinable()) {
                t.join();
            }
        }
    }

    void addSession(const Session& session) {
        std::lock_guard<std::mutex> lock(mtx);

        // Check queue size and decide on appropriate action, such as rejecting the request or waiting until there's space available
        if (sessionQueue.size() >= maxSessions) {
            throw std::runtime_error("Max number of sessions reached");
        }

        sessionQueue.push(session);
    }

private:
    void worker() {
        // Worker thread function that processes a queue of sessions in FIFO order
        while (true) {
            std::unique_lock<std::mutex> lock(mtx);

            if (!sessionQueue.empty()) {
                Session session = std::move(sessionQueue.front());
                sessionQueue.pop();

                lock.unlock(); // Unlock to allow other threads to add sessions while the current one processes

                // Process session (e.g., call external APIs, manage resources)
            } else {
                // Wait for new sessions or check exit condition
            }
        }
    }
};
