import org.apache.http.*;
import org.apache.http.client.methods.*;
import org.apache.http.impl.client.*;
public class MonitoringAgent {
    private static final int RETRIES = 3; // number of retries before giving up
    private static final long BACKOFF_MILLIS = 2000; // initial backoff time in ms
    public void performHealthCheck(String url) throws Exception {
        CloseableHttpClient httpclient = HttpClients.createDefault();
        for (int i = 1; i <= RETRIES; i++) {
            try {
                HttpGet request = new HttpGet(url); // create a GET request
                CloseableHttpResponse response = httpclient.execute(request); // execute the request
                int statusCode = response.getStatusLine().getStatusCode(); // get HTTP status code
                if (statusCode == HttpStatus.SC_OK) { // check the result
                    return;
                } else {
                    System.out.println("Received HTTP " + statusCode);
                    Thread.sleep(BACKOFF_MILLIS * i); 
                }
            } catch (Exception e) {
                System.out.println("Error: "+e.getMessage());
            }
        }
    }
}
```
