```c
typedef struct {
    int id;
    pthread_t thread;
} worker_t;

worker_t *workers = NULL;
int worker_count = 0;

void init_pool(int count) {
    workers = malloc(sizeof(worker_t) * count);
    // Initialize each worker
    for (int i = 0; i < count; i++) {
        worker_t *worker = &workers[i];
        worker->id = i + 1;
        pthread_create(&worker->thread, NULL, worker_task, worker);
    }
    worker_count = count;
