typedef struct DataTransferEvent {
    double timestamp;
    char source_ip[46]; // Max length of an IPv6 address is 45 characters
    char destination_ip[46]; 
    unsigned int packet_size;
    char protocol_type[10]; // Assume the max length for a protocol type is 9 characters
    struct DataTransferEvent *next;
} DataTransferEvent;

DataTransferEvent *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addEvent(double timestamp, char* source_ip, char* destination_ip, unsigned int packet_size, char* protocol_type) {
    pthread_mutex_lock(&lock);

    DataTransferEvent *new_event = (DataTransferEvent*) malloc(sizeof(DataTransferEvent));
    new_event->timestamp = timestamp;
    strncpy(new_event->source_ip, source_ip, 45);
    strncpy(new_event->destination_ip, destination_ip, 45);
    new_event->packet_size = packet_size;
    strncpy(new_event->protocol_type, protocol_type, 9);

    new_event->next = head;
    head = new_event;

    pthread_mutex_unlock(&lock);
}

DataTransferEvent* getEvents() {
    DataTransferEvent *current = NULL;

    pthread_mutex_lock(&lock);

    if(head != NULL) {
        current = head;

        // Remove the first node from the list
        head = head->next;
    }

    pthread_mutex_unlock(&lock);

    return current;
}

