    atomic_fetch_add(&readerCount, 1);
    if (atomic_load(&readerCount) == 1) {
        // Lock writing operations until all reading is done
        pthread_mutex_lock(&globalLock); 
    }

    Record* record = NULL; // Code to read the record from storage...

