    pthread_mutex_init(&manager->lock, NULL);
    manager->records = NULL;
    manager->size = 0;
    return manager;
}

void record_manager_destroy(RecordManager* manager) {
    for (int i = 0; i < manager->size; ++i) {
        free(manager->records[i]->description);
        free(manager->records[i]);
    }
    if (manager->records != NULL) {
        free(manager->records);
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int record_manager_add(RecordManager* manager, int key, long offset, const char* description) {
    Record* record = malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    record->description = strdup(description);

    pthread_mutex_lock(&manager->lock);
    manager->records = realloc(manager->records, sizeof(Record*) * (manager->size + 1));
    manager->records[manager->size] = record;
    manager->size++;
    pthread_mutex_unlock(&manager->lock);

    return 0; // or appropriate error codes
}
