// Required modules
const fs = require('fs');
const path = require('path');
const readline = require('readline');
const {promisify} = require('util');
const loggerService = require('./loggerService')(config); // Assume we have a logging service

// Promisified functions
const fsReaddirAsync = promisify(fs.readdir);
const fsStatAsync = promisify(fs.stat);
const fsCreateReadStreamAsync = promisify(fs.createReadStream);
const loggerServiceLogAsync = promisify(loggerService.log);

class FileProcessor {
    constructor() {
        this.fileQueue = async.queue((task, callback) => {
            // Process the file asynchronously
            let data = await this.processFile(task.filename);

            // Logging data
            loggerServiceLogAsync({message: 'Processed file', level: 'info', filename: task.filename});

            callback();
        }, 10); // Concurrency limit is set to 10
    }

    async processDirectory(directory, extension) {
        let files = await fsReaddirAsync(directory);

        for (let file of files) {
            let filename = `${directory}/${file}`;
            let stats = await fsStatAsync(filename);

            if (stats.isDirectory()) {
                // Recursively process sub-directories
                this.processDirectory(filename, extension);
            } else if (path.extname(filename) === `.${extension}`) {
                // Enqueue file processing task
                this.fileQueue.push({filename});
            }
        }

        // Wait for all files to be processed
        await this.fileQueue.drain();
    }

    async processFile(filename) {
        let readStream = await fsCreateReadStreamAsync(filename);
        let rl = readline.createInterface({input: readStream});

        // Process the file line by line
        for await (const line of rl) {
            console.log(`Line from ${filename}: ${line}`);

            // Add logic to aggregate contents into a JSON response here...
        }
    }
}
```
