public class GameServerConfigService : IHostedService, IDisposable
{
    private readonly ILogger<GameServerConfigService> _logger;
    private Timer _timer;
    private static SemaphoreSlim semaphore = new SemaphoreSlim(1, 1); // ensure only one thread can execute at a time
    private static ConcurrentDictionary<string, GameServerSettings> cache = new ConcurrentDictionary<string, GameServerSettings>();
    private ConnectionFactory factory;
    private IConnection connection;
    private IModel channel;
    private IDatabase redisDB;

    public GameServerConfigService(ILogger<GameServerConfigService> logger)
    {
        _logger = logger;
        // RabbitMQ configuration and setup
        factory = new ConnectionFactory() { HostName = "localhost" };
        connection = factory.CreateConnection();
        channel = connection.CreateModel();

        // Redis configuration and setup
        var redis = ConnectionMultiplexer.Connect("localhost");
        redisDB = redis.GetDatabase();
    }

    public Task StartAsync(CancellationToken cancellationToken)
    {
        _logger.LogInformation("GameServerConfigService is starting.");

        // Timer setup to fetch game server settings every minute
        _timer = new Timer(DoWork, null, TimeSpan.Zero, 
            TimeSpan.FromMinutes(1));

        return Task.CompletedTask;
    }

    private async void DoWork(object state)
    {
        // Ensure only one thread can execute this at a time
        if (!semaphore.Wait(0)) 
            return;

        try
        {
            var settings = await FetchSettingsFromAPIAsync();

            // Update local cache and Redis
            cache[settings.Id] = settings;
            redisDB.StringSet(settings.Id, JsonConvert.SerializeObject(settings));

            // Publish an event to RabbitMQ
            var message = JsonConvert.SerializeObject(new { GameServerSettingsUpdated = true });
            var body = Encoding.UTF8.GetBytes(message);
            channel.BasicPublish(exchange: "", routingKey: "game-server-settings", basicProperties: null, body: body);
        }
        finally
        {
            semaphore.Release();
        }
    }

    private async Task<GameServerSettings> FetchSettingsFromAPIAsync()
    {
        // Fetch settings from external API and handle dynamic structure changes
        // Implement your custom logic here to fetch and process the data as per your requirement
    }

    public Task StopAsync(CancellationToken cancellationToken)
    {
        _logger.LogInformation("GameServerConfigService is stopping.");

        _timer?.Change(Timeout.Infinite, 0);

        return Task.CompletedTask;
    }

    public void Dispose()
    {
        // Clean up RabbitMQ and Redis connections
        channel?.Close();
        connection?.Close();
    }
}
```
