["```rust
use tokio::time::Instant;
use std::time::Duration;
use futures_util::stream::FuturesUnordered;

pub async fn measure_async<F>(funcs: Vec<F>) -> Duration
where
    F: Send + 'static + Sync + Fn() -> (),
{
    let start = Instant::now();
    let mut futures = FuturesUnordered::new();

    for func in funcs {
        futures.push(futures::future::lazy(func))
    }

    futures::executor::block_on(futures);

    start.elapsed()
}
```

The `measure_async` function takes a vector of closures and runs them asynchronously using the `FuturesUnordered` struct from the `futures-util` crate. It measures the time taken to run all the futures and returns this duration. Note that `Fn() -> ()` is a trait object representing a function that takes no arguments and returns nothing.
"]

