    return bookNamesInText.filter(bookName => BOOK_NAMES.has(bookName));
  }

  async validateWithAPI(book, apiUrl) {
    try {
      const response = await fetch(`${apiUrl}/validate?book=${encodeURIComponent(book)}`);
      if (!response.ok) throw new Error('Invalid API Response');
      return await response.json();
    } catch (err) {
