      console.error(`Failed to validate book with ${apiUrl}`);
      throw err;
    }
  }

  async validateBookReferences(bookNames) {
    const validationPromises = [];
    for (const apiUrl of API_URLS) {
      for (const bookName of bookNames) {
        if (!this.cache[bookName]) { // check cache first to prevent making duplicate requests
          validationPromises.push(this.validateWithAPI(bookName, apiUrl));
        } else {
          console.log(`Serving ${bookName} from cache`);
        }
      }
    }

    const results = await Promise.allSettled(validationPromises);
    for (const result of results) {
      if (result.status === 'fulfilled') {
        this.cache[result.value.bookName] = result.value; // save to cache
      } else {
        console.error('Validation error:', result.reason);
      }
    }
  }

  async processText(text) {
    const bookReferences = await this.extractBookReferences(text);
    await this.validateBookReferences(bookReferences);
  }
}
