```java
import java.io.IOException;
import java.nio.channels.SocketChannel;
import java.util.concurrent.*;
import javax.net.ssl.SSLContext;
import javax.net.ssl.SSLEngine;
import javax.net.ssl.TrustManagerFactory;

public class AsyncConnectionPool {
    private static final String TLS_VERSION = "TLSv1.2";
    private static final ExecutorService executorService = Executors.newFixedThreadPool(10);

    private SSLContext sslContext;
    private ConcurrentHashMap<String, SocketChannel> connectionPool;

    public AsyncConnectionPool() throws Exception {
        this.connectionPool = new ConcurrentHashMap<>();
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        SSLContext ctx = SSLContext.getInstance("TLS");
        ctx.init(null, tmf.getTrustManagers(), null);
        this.sslContext = ctx;
    }

    public Future<SocketChannel> getConnection(String endpoint) {
        return executorService.submit(() -> {
            SocketChannel socketChannel = connectionPool.computeIfAbsent(endpoint, key -> {
                try {
                    SocketChannel channel = SocketChannel.open();
                    SSLEngine sslEngine = sslContext.createSSLEngine(endpoint, 443);
                    channel.configureBlocking(false);
                    channel.connect(new InetSocketAddress(endpoint, 443));
                    while (!channel.finishConnect()) ;
                    // configure SSL settings and do handshake here...

                    return channel;
                } catch (IOException e) {
                    throw new RuntimeException("Failed to establish connection", e);
                }
            });

            if (!socketChannel.isOpen() || !socketChannel.isConnected()) {
                connectionPool.remove(endpoint, socketChannel);
                throw new RuntimeException("Connection failed");
            }

            return socketChannel;
        });
    }
}
``` 
