Here is a simplified version of what your Client struct could look like:
```rust
extern crate reqwest;
extern crate rusqlite;
use std::sync::Arc;
use rusqlite::{params, Connection, Result};
use reqwest::Client as ReqwestClient;

pub struct Client {
    http_client: Arc<ReqwestClient>,
    sql_conn: Arc<Connection>,
}

impl Client {
    pub fn new(http_base_url: &str, db_path: &str) -> Result<Self> {
        let http_client = ReqwestClient::builder()
            .build()?;

        let sql_conn = Connection::open(db_path)?;

        Ok(Self {
            http_client: Arc::new(http_client),
            sql_conn: Arc::new(sql_conn),
        })
    }

    pub async fn http_get(&self, endpoint: &str) -> Result<reqwest::Response> {
        self.http_client.get(endpoint).send().await
    }

    pub async fn sql_exec(&self, query: &str, params: Vec<rusqlite::types::Value>) -> Result<()> {
        let mut stmt = self.sql_conn.prepare(query)?;
        stmt.execute(params, |row| row)?;
        self.sql_conn.commit()?;
        Ok(())
    }
}
```
This is a very basic example and would need to be extended with the necessary error handling and configuration options for your use case. Also, you will need proper authentication token management, retry logic, caching strategies and possibly threading models suitable for high concurrency scenarios. 

