                } catch (IOException e) {
                    // Handle the exception accordingly.
                }
            }
        }, executor).whenComplete((unused, throwable) -> {
            if (throwable != null) {
                // Log or handle the error here.
            } else {
                meterRegistry.counter("command.success").increment();
            }
        });
    }

