List* createNode(NFAPI_CRC_INDICATION_PDU_T *data) {
    List *node = (List*) malloc(sizeof(List));
    node->data = data;
    node->next = NULL;
    return node;
}

void addToList(NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&lock);

    if (head == NULL) {
        head = createNode(data);
    } else {
        List *temp = head;
        while (temp->next != NULL) temp = temp->next;
        temp->next = createNode(data);
    }

    pthread_mutex_unlock(&lock);
}

void removeFromList(NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&lock);

    List **tracer = &head;
    while ((*tracer)->data != data) tracer = &((*tracer)->next);
    List *nodeToRemove = *tracer;
    *tracer = (*tracer)->next;
    free(nodeToRemove);

    pthread_mutex_unlock(&lock);
}

