```CSharp
using System;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading.Tasks;

public class TcpClient : IDisposable
{
    private readonly Socket socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
    public async Task ConnectAsync(string host, int port)
    {
        await socket.ConnectAsync(IPAddress.Parse(host), port);
    }

    public void Dispose()
    {
        socket?.Dispose();
    }
}

public class TcpListener : IDisposable
{
    private readonly Socket socket = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
    public async Task StartAsync(int port)
    {
        socket.Bind(new IPEndPoint(IPAddress.Any, port));
        socket.Listen(100);

        while (true)
        {
            var clientSocket = await socket.AcceptAsync();
            // Handle the client connection asynchronously...
            _ = Task.Run(() => HandleClientConnectionAsync(clientSocket));
        }
    }

    private async Task HandleClientConnectionAsync(Socket clientSocket)
    {
        var buffer = new byte[1024];
        while (true)
        {
            int receivedBytes = await clientSocket.ReceiveAsync(buffer, SocketFlags.None);
            if (receivedBytes == 0) break; // Client disconnected

            string message = Encoding.UTF8.GetString(buffer, 0, receivedBytes);
            Console.WriteLine("Client says: " + message);
        }
    }

    public void Dispose()
    {
        socket?.Dispose();
    }
}
```

This is a very basic example and doesn't cover all the requirements like multi-threading, security, error handling or load balancing etc. You may need to enhance this further to address your specific needs or use an existing library/framework that provides these capabilities if possible. The .NET framework itself has built-in classes for managing TCP connections such as `System.Net.Sockets.TcpClient` and `System.Net.Sockets.TcpListener` but they might not meet all of your requirements.
