['Here's a basic implementation of your requirements in C#:

```csharp
using System;
using System.Threading;

public interface ILogger {
    void Log(string message);
}

public class DynamicRandomValueGenerator {
    private readonly Random randomGenerator = new Random();
    private readonly SemaphoreSlim semaphore = new SemaphoreSlim(1, 1); // for thread safety

    public int minValue { get; set; }
    public int maxValue { get; set; }
    public bool logEnabled { get; set; }
    private ILogger logger;

    public DynamicRandomValueGenerator(int min, int max) {
        if (min > max) throw new ArgumentOutOfRangeException("Min value cannot be greater than max value.");

        this.minValue = min;
        this.maxValue = max;
    }

    public float GetRandomFloat() => (float)(randomGenerator.NextDouble() * (maxValue - minValue) + minValue);

    public float GetRandomFloatExclusive() {
        double value = randomGenerator.NextDouble();

        return (float)((value > 0 ? value : 1) * (maxValue - minValue - 1) + minValue + 1);
    }

    public int GetRandomInt() => randomGenerator.Next(minValue, maxValue + 1);

    public int GetRandomIntExclusive() => randomGenerator.Next(minValue + 1, maxValue);

    public void SetLogger(ILogger logger) { this.logger = logger; }

    public ILogger GetLogger() { return logger; }

    private void Log(string message) {
        if (logEnabled && logger != null) {
            try {
                logger.Log($"{DateTime.Now}: {message}");
            } catch (Exception e) {
                // Retry logging operation after a delay on transient failures
                Thread.Sleep(100);
                Log(message);
            }
        }
    }

    public void ReleaseResources() {
        semaphore.Dispose();  // Disposes the SemaphoreSlim instance
        randomGenerator?.Dispose(); // Disposes the Random instance if it's not null

        // This step may vary depending on external dependencies
        (logger as IDisposable)?.Dispose(); // If logger implements IDisposable, dispose it
    }
}
``` 

Please note that handling logging failures and concurrency is simplified in this example for the sake of brevity. In a production environment you would want more robust error handling and potentially retry logic using exponential backoff or similar techniques. Also ensure to handle any potential exceptions from disposing resources.
