    headers = curl_slist_append(headers, "charset: utf-8");

    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());  
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data.c_str());  // Set the POST data
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);  

    CURLcode res = curl_easy_perform(curl);  // Perform the request
    if (res != CURLE_OK) {
        throw std::runtime_error("Could not perform curl request");
    }

    long httpCode = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &httpCode);  // Get the HTTP status code

    if (httpCode != 200) {
        throw std::runtime_error("HTTP response code was not 200");
    }

    curl_easy_cleanup(curl);  // Clean up the easy session
}
```

