```cpp
#include <iostream>
#include <thread>
#include <vector>
#include <mutex>
#include <condition_variable>

class Task {
public:
    virtual void run() = 0;  // This needs to be implemented by derived classes.
};

// The thread pool where tasks are submitted and executed.
class ThreadPool {
public:
    void submit(std::shared_ptr<Task> task) {
        std::lock_guard<std::mutex> lock(mMutex);
        mTasks.push_back(task);
        mCondition.notify_one();
    }

private:
    // Thread function that fetches tasks from the queue and runs them.
    void workerThread() {
        while (true) {
            std::shared_ptr<Task> task;
            {
                std::unique_lock<std::mutex> lock(mMutex);
                mCondition.wait(lock, [this] { return !mTasks.empty(); });
                task = mTasks.front();
                mTasks.pop_front();
            }
            task->run();
        }
    }

    std::vector<std::thread> mWorkers;  // The worker threads.
    std::deque<std::shared_ptr<Task>> mTasks;  // Queue of tasks to execute.
    std::mutex mMutex;  // Mutex for synchronization.
    std::condition_variable mCondition;  // Condition variable for signaling task availability.
};
```

