public class DynamicDocumentProcessor {
    private final DocumentProcessingService documentProcessingService;
    private final ExecutorService executorService = Executors.newFixedThreadPool(10);

    // Redis Configuration
    Config config = new Config();
    config.useSingleServer().setAddress("redis://localhost:6379");
    RedissonClient redisson = Redisson.create(config);
    RMapCache<String, byte[]> cacheMap = redisson.getMapCache("documentCache");

    // ConcurrentHashMap for caching results
    private final Cache<String, Future<byte[]>> pendingTasks = new Cache<>();

    public DynamicDocumentProcessor(DocumentProcessingService documentProcessingService) {
        this.documentProcessingService = documentProcessingService;
    }

    // Convert Method with Async support
    public CompletableFuture<byte[]> convertAsync(String input, String format) {
        return CompletableFuture.supplyAsync(() -> {
            byte[] cachedDocument = cacheMap.getOrDefault(input + "_" + format, null);

            if (cachedDocument != null) {
                System.out.println("Found in Cache: " + input + "_" + format);
                return cachedDocument;
            } else {
                byte[] convertedDoc = documentProcessingService.convert(input, format);
                cacheMap.put(input + "_" + format, convertedDoc, 10, TimeUnit.MINUTES);

                System.out.println("Cached: " + input + "_" + format);
                return convertedDoc;
            }
        }, executorService);
    }

    // Main method for conversion
    public byte[] convert(String input, String format) {
        Future<byte[]> future = convertAsync(input, format).join();

        try {
            return future.get();
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException("Failed to process document: " + input);
        }
    }
}
