typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ARRAY_SIZE 10000

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    int count;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    da->count = 0;
    da->array = calloc(MAX_ARRAY_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void insertElement(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    assert(da->count < MAX_ARRAY_SIZE);

    pthread_mutex_lock(&da->lock);
    da->array[da->count++] = element;
    pthread_mutex_unlock(&da->lock);
}

NFAPI_CRC_INDICATION_PDU_T getElement(DynamicArray *da, int index) {
    assert(index >= 0 && index < da->count);

    NFAPI_CRC_INDICATION_PDU_T element;
    pthread_mutex_lock(&da->lock);
    element = da->array[index];
    pthread_mutex_unlock(&da->lock);

    return element;
}

void destroyDynamicArray(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->lock);
    free(da);
}
```
This design uses a `pthread_mutex` to ensure thread-safe operations. 

