typedef struct ArrayElement {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ArrayElement *next;
} ArrayElement;

ArrayElement* array[10000]; // Global fixed size array
pthread_rwlock_t rwlock = PTHREAD_RWLOCK_INITIALIZER;
int arraySize = 0;

void addElement(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_rwlock_wrlock(&rwlock); // Acquire write lock to ensure exclusive access

    if (arraySize < 10000) {
        ArrayElement *newEl = malloc(sizeof(ArrayElement));
        newEl->data = data;
        newEl->next = NULL;

        array[arraySize++] = newEl; // Store the new element in the array and increment size
    } else {
        printf("Cannot add more elements, array is full.\n");
    }

    pthread_rwlock_unlock(&rwlock); // Release lock after operation complete
}

NFAPI_CRC_INDICATION_PDU_T getElement(int index) {
    NFAPI_CRC_INDICATION_PDU_T result;
    memset(&result, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Initialize with default values

    pthread_rwlock_rdlock(&rwlock); // Acquire read lock to allow concurrent reads

    if (index >= 0 && index < arraySize) {
        result = array[index]->data;
    } else {
        printf("Index out of bounds.\n");
    }

    pthread_rwlock_unlock(&rwlock); // Release lock after operation complete

    return result;
}
```

