```c
#include <stdint.h>
#define MAX_INDICATIONS 10000

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T indications[MAX_INDICATIONS];

void generate_crc_indications(uint32_t crc) {
    for (int i = 0; i < MAX_INDICATIONS; ++i) {
        indications[i].RX_UE_INFORMATION_TAG = (crc >> i) & 1;
        indications[i].RNTI = crc * i % UINT32_MAX;
        indications[i].CRC_INDICATION_REL8_TAG = (indications[i].RX_UE_INFORMATION_TAG + indications[i].RNTI) % 256;
    }
}
