```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Structure representing a log message
typedef struct {
    char* content;
    int severity;
} LogMessage;

// Forward declaration of the logger type
typedef struct Logger Logger;

// Type definition for logging function
typedef void (*LogFunc)(Logger*, const LogMessage);

// Structure representing a logger
struct Logger {
    pthread_mutex_t mutex; // Mutex to ensure thread safety
    int maxQueueSize;     // Maximum size of the queue
    LogMessage* queue;    // Queue for buffering log messages
    int queueCount;       // Current number of items in the queue
    LogFunc logFunction;  // Function used to send logs
};

// Initializes a logger with a specified maximum queue size and logging function
Logger* init_logger(int maxQueueSize, LogFunc logFunction) {
    Logger* logger = malloc(sizeof(Logger));
    pthread_mutex_init(&logger->mutex, NULL);

    logger->maxQueueSize = maxQueueSize;
    logger->queueCount = 0;
    logger->queue = calloc(maxQueueSize, sizeof(LogMessage));
    logger->logFunction = logFunction;

    return logger;
}

// Adds a message to the logger's queue
void add_message(Logger* logger, const LogMessage* msg) {
    pthread_mutex_lock(&logger->mutex);

    if (logger->queueCount < logger->maxQueueSize) {
        logger->queue[logger->queueCount].content = strdup(msg->content);
        logger->queue[logger->queueCount].severity = msg->severity;
        logger->queueCount++;
    } else {
        // Handle the case where the queue is full (e.g., discard new logs)
    }

    pthread_mutex_unlock(&logger->mutex);
}

// Function for sending log messages to an external service
void send_logs(Logger* logger, const LogMessage* msg) {
    // Send the message to the external logging service
}

// Flushes all queued logs and frees memory
void flush_and_destroy(Logger* logger) {
    pthread_mutex_lock(&logger->mutex);

    for (int i = 0; i < logger->queueCount; i++) {
        free(logger->queue[i].content);
    }

    free(logger->queue);
    pthread_mutex_destroy(&logger->mutex);
    free(logger);
}
```

This is a basic example. You'll need to adapt this for your specific use case, e.g., handling network failures or implementing fallback strategies when the external logging service is unavailable. Furthermore, the memory allocation in this example can be optimized by using memory pools, which would avoid frequent malloc and free calls but would still require to deal with memory fragmentation.
