#include "database_library.h" 

CURL *handle;
char errbuf[CURL_ERROR_SIZE];

int loadResource(const char* url) {
    handle = curl_easy_init(); // Initialize the curl session.
    if (!handle) return -1;

    curl_easy_setopt(handle, CURLOPT_URL, url); // Set the URL to download from.
    curl_easy_setopt(handle, CURLOPT_ERRORBUFFER, errbuf); 

    int retryCount = 0;
    while (retryCount < 3) {
        if (curl_easy_perform(handle) != CURLE_OK) {
            fprintf(stderr, "Failed to download: %s\n", errbuf);
            ++retryCount;
            continue;
        }

        // Check freshness and handle stale data.
        if (!isFreshData()) {
            updateStaleData();
        }

        return 0; // Downloaded successfully.
    }

    curl_easy_cleanup(handle); // Clean up the curl session.
    return -1; // Failed to download after retries.
}
```
