use std::sync::mpsc;
use crossbeam_channel::Receiver;
use crossbeam_channel::Sender;

pub struct XmlQueue {
    sender: Sender<String>,
    receiver: Receiver<String>,
}

impl XmlQueue {
    pub fn new() -> (XmlQueue, JoinGuard<Receiver<String>>) {
        let (sx, rx) = mpsc::channel();
        (XmlQueue { sender: sx, receiver: rx }, rx.into_shared())
    }

    pub fn send(&self, xml: String) -> Result<(), ()> {
        match self.sender.send(xml) {
            Ok(_) => Ok(()),
            Err(_) => Err(()),
        }
    }
}
