['```java
import java.io.*;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class EmployeeService {
    private final OAuth2Credentials credentials;
    private final ExternalAPIClient externalClient;
    private final CacheManager cacheManager;
    private ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public EmployeeService(OAuth2Credentials credentials, ExternalAPIClient externalClient) {
        this.credentials = credentials;
        this.externalClient = externalClient;
        cacheManager = new CacheManager();
    }

    public Employee fetchEmployeeDetails(int employeeId, boolean bypassCache) throws Exception {
        Lock readLock = lock.readLock();
        readLock.lock();
        try {
            if (!bypassCache && cacheManager.contains(employeeId)) {
                return (Employee) cacheManager.get(employeeId);
            } else {
                OAuth2Credentials oauth = credentials.refreshIfExpired();
                Employee employee = externalClient.fetchEmployeeDetails(oauth, employeeId);

                Lock writeLock = lock.writeLock();
                writeLock.lock();
                try {
                    cacheManager.put(employeeId, employee);
                } finally {
                    writeLock.unlock();
                }

                return employee;
            }
        } finally {
            readLock.unlock();
        }
    }

    public MoSTState loadStateObject(String filePath) throws Exception {
        ObjectInputStream in = null;

        try {
            FileInputStream fin = new FileInputStream(filePath);
            in = new ObjectInputStream(fin);

            Object obj = in.readObject();

            if (obj instanceof MoSTState) {
                return (MoSTState) obj;
            } else {
                return null;
            }
        } catch (FileNotFoundException e) {
            throw new Exception("File not found at " + filePath);
        } catch (IOException | ClassNotFoundException e) {
            throw new Exception("Error reading object from file", e);
        } finally {
            if(in != null){
                in.close();
            }
        }
    }
}
```
