```java
import java.io.*;
import java.nio.file.Path;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

public class SystemCommandExecutor {
    private static final AtomicInteger SUCCESSFUL_DESERIALIZATIONS = new AtomicInteger(0);
    private static final int MAX_RETRIES = 3;

    public void executeCommandAndProcessOutput(String command, Map<String, String> env, Path workingDir) throws IOException {
        Process process = null;

        try {
            ProcessBuilder pb = new ProcessBuilder(command.split(" "));
            pb.directory(workingDir.toFile());

            if (env != null) {
                Map<String, String> procEnvironment = pb.environment();
                procEnvironment.putAll(env);
            }

            process = pb.start();

            InputStreamConsumer stdoutConsumer = new InputStreamConsumer(process.getInputStream(), System.out::println);
            InputStreamConsumer stderrConsumer = new InputStreamConsumer(process.getErrorStream(), System.err::println);

            // Start consumers, they will print command's output to the standard streams
            stdoutConsumer.start();
            stderrConsumer.start();

            process.waitFor();
        } catch (InterruptedException e) {
            throw new IOException(e);
        } finally {
            if (process != null) {
                process.destroy();
            }
        }
    }

    public Object deserializeObject(byte[] data) throws IOException, ClassNotFoundException {
        for (int i = 0; i < MAX_RETRIES; i++) {
            try (ByteArrayInputStream bais = new ByteArrayInputStream(data); 
                 ObjectInputStream ois = new ObjectInputStream(bais)) {
                Object obj = ois.readObject();
                SUCCESSFUL_DESERIALIZATIONS.incrementAndGet();
                return obj;
            } catch (ClassNotFoundException e) {
                System.err.println("Failed to deserialize object, retrying...");
                if (i == MAX_RETRIES - 1) throw e; // Last retry failed with CNFE
            }
        }

        return null; // If we got here, all retries have failed
    }
}
```
This code also includes a helper class `InputStreamConsumer` that consumes an input stream and processes its data:

```java
import java.io.*;
import java.util.function.Consumer;

public class InputStreamConsumer extends Thread {
    private final BufferedReader reader;

    public InputStreamConsumer(InputStream is, Consumer<String> consumer) {
        this.reader = new BufferedReader(new InputStreamReader(is));
        this.consumer = consumer;
    }

    @Override
    public void run() {
        String line;

        try {
            while ((line = reader.readLine()) != null) {
                consumer.accept(line);
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
``` 

This code assumes that the command being executed is a simple string containing all necessary arguments. It also assumes that the `executeCommandAndProcessOutput` method will only be called from a single thread, or that all calls to it are synchronized appropriately. Also, you may need to adjust this based on your specific needs such as error handling, command execution timeout and retry policy, etc.
