#include <stdlib.h>
#include <pthread.h>
#include "NFAPI_CRC_INDICATION_PDU_T.h"  // Replace with actual header file for NFAPI_CRC_INDICATION_PDU_T

typedef struct arraylist {
    int size;
    int capacity;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T** elements;  // Using an array of pointers for dynamic growth
} ArrayList;

// Initialize the arraylist with initial capacity
void init(ArrayList* al, int capacity) {
    al->size = 0;
    al->capacity = capacity;
    al->elements = (NFAPI_CRC_INDICATION_PDU_T**)calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_mutex_init(&al->lock, NULL);
}

// Add an element to the arraylist
void add(ArrayList* al, NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&al->lock);  // Acquire lock before accessing data
    if (al->size == al->capacity) {
        grow(al);  // Double the capacity when array is full
    }
    al->elements[al->size++] = element;
    pthread_mutex_unlock(&al->lock);  // Release lock after modifying data
}

// Grow the arraylist by doubling its capacity
void grow(ArrayList* al) {
    NFAPI_CRC_INDICATION_PDU_T** newElements = (NFAPI_CRC_INDICATION_PDU_T**)calloc(al->capacity * 2, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    for (int i = 0; i < al->size; ++i) {
        newElements[i] = al->elements[i];
    }
    free(al->elements);  // Free the old array
    al->capacity *= 2;
    al->elements = newElements;
}
```
