['Below is an overview of a basic setup for your Python-based configuration management platform:

```python
import os
import requests
from jinja2 import Environment, FileSystemLoader
from UnityEngine import Random

class ConfigManager:
    def __init__(self, env):
        self.env = env
        self.jinja_env = Environment(loader=FileSystemLoader('./templates'))
        self.configs = {}

    def fetch_settings(self):
        api1 = os.getenv("API1")  # Fetch from .env file or other secure source
        api2 = os.getenv("API2")

        try:
            response1 = requests.get(api1)
            response2 = requests.get(api2)

            if response1.status_code != 200 or response2.status_code != 200:
                print("Error fetching settings from APIs")
        except Exception as e:
            print(f"Exception occurred while fetching configurations: {e}")

        self.configs = {**response1.json(), **response2.json()}

    def generate_template(self, template_name):
        try:
            template = self.jinja_env.get_template(f'{template_name}.j2')
            return template.render(**self.configs)
        except Exception as e:
            print(f"Exception occurred while generating template: {e}")

    def save_to_file(self, content, filename):
        with open(filename, 'w') as f:
            f.write(content)

    def generate_configs(self):
        self.fetch_settings()
        for template in ["template1", "template2"]:  # replace with your actual templates
            content = self.generate_template(template)
            filename = f'{self.env}_{template}.conf'  # adjust the filename format as needed
            self.save_to_file(content, filename)

    def generate_random_value(self, min_val, max_val):
        return Random.Range(min_val, max_val)
```

