#include <stdlib.h>
#include <Python.h>

void initRecords(long **recordsArray, int numOfRecords) {
    Py_Initialize();

    PyObject *pName, *pModule, *pDict, *pFunc;
    PyObject *pArgs, *pValue;
    int i;

    pName = PyUnicode_FromString("pythonScript"); // replace with your python script name
    /* Error checking of pName left out */

    pModule = PyImport_Import(pName);
    Py_DECREF(pName);

    if (pModule != NULL) {
        pFunc = PyObject_GetAttrString(pModule, "getRecords"); // replace with your python function name
        /* pFunc is a new reference */

        if (pFunc && PyCallable_Check(pFunc)) {
            pArgs = PyTuple_New(1);
            for (i = 0; i < numOfRecords; ++i) {
                pValue = PyLong_FromLong(recordsArray[i]); // assuming that recordsArray is an array of longs. You might need to adjust this depending on the actual structure of your data.
                if (!pValue) {
                    Py_DECREF(pArgs);
                    Py_DECREF(pModule);
                    fprintf(stderr, "Cannot convert argument\n");
                    exit(1);
                }

                /* pValue reference stolen here: */
                PyTuple_SetItem(pArgs, i, pValue);
            }

            PyObject_CallObject(pFunc, pArgs); // Call python function with recordsArray as argument
            Py_DECREF(pArgs);
        } else {
            fprintf(stderr,"Cannot find function\n");
        }

        /* Clean up */
        Py_XDECREF(pFunc);
        Py_DECREF(pModule);
    } else {
        PyErr_Print();
        fprintf(stderr, "Failed to load module\n");
    }

    if (Py_FinalizeEx() < 0) {
        exit(120);
    }
}
```

This code assumes you have a Python script with a function `getRecords` that accepts an array of longs as input. You would need to replace "pythonScript" and "getRecords" with the actual names of your python file and function respectively. It also assumes that your recordsArray is a 1-dimensional array of longs, which may not be true in your specific use case.
