namespace fs = boost::filesystem;

struct CustomDataStructure {
    // ... your custom data structure here ...
};

CustomDataStructure loadFromBinaryFile(const std::string& filePath) {
    if(!fs::exists(filePath)) {
        throw std::runtime_error("The specified file does not exist!");
    }

    fs::path boostPath = filePath;

    std::ifstream ifs(boostPath.string(), std::ios::binary);
    if(!ifs) {
        throw std::runtime_error("Failed to open the file for reading!");
    }

    boost::archive::binary_iarchive ia(ifs);
    CustomDataStructure data;
    try{
        ia >> data;
    } catch (boost::archive::archive_exception& ex) {
        throw std::runtime_error("Failed to deserialize the binary file: " + std::string(ex.what()));
    }

    return data;
}
