Firstly, you need to define 'node' structure. You may also want to use locks or atomic operations to ensure thread-safety. Below is a simple example. Note that locking and timestamp API integration have been omitted for brevity:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct node {
    char *string;
    long timestamp;
    struct node* next; 
} Node;

Node* create_node(char *str) {
    Node* newNode = malloc(sizeof(Node));
    newNode->string = str;
    newNode->timestamp = getTimestamp(); //This should be a thread-safe function that calls your time-stamping API.
    newNode->next = NULL; 

    return newNode;
}
```

Then you would need to implement functions for insertion and deletion:

```c
void insert_node(Node **head, char *str) {
    Node* nodeToAdd = create_node(str);

    // Lock here...
    if (*head == NULL || (*head)->timestamp > nodeToAdd->timestamp) { 
        nodeToAdd->next = *head; 
        *head = nodeToAdd; 
    } else {
        Node* current = *head;

        while (current->next != NULL && current->next->timestamp < nodeToAdd->timestamp) { 
            current = current->next; 
        }

        nodeToAdd->next = current->next; 
        current->next = nodeToAdd; 
    }
    // Unlock here...
}

void delete_node(Node **head, char *str) {
    Node* temp = *head, *prev = NULL;

    // Lock here...
    if (temp != NULL && strcmp(temp->string, str) == 0) { 
        *head = temp->next; 
        free(temp); 
        return;
    }

    while (temp != NULL && strcmp(temp->string, str) != 0) {
        prev = temp; 
        temp = temp->next; 
    }

    if (temp == NULL) {
        // Unlock here...
        return;
    } 

    prev->next = temp->next; 

    free(temp); 
    // Unlock here...
}
```

Finally, you need to implement a cleanup function and consider error handling:

```c
void delete_list(Node** head) {
    while(*head != NULL) {
        Node* nextNode = (*head)->next;
        free((*head));
        *head = nextNode;
    }
}
```
