const express = require('express');
const QueueService = require('./services/QueueService');
let jobQueue = new QueueService("job_queue");
let app = express();

app.post('/submitJob', async (req, res) => {
    let jobData = req.body; // Assume the request body contains the job data.
    try{
        await jobQueue.addJobToQueue(jobData);
        res.status(200).send('Job added to queue');
    }catch(error){
        console.log("Error while adding job: ", error);
        res.status(500).send('Failed to add job');
    }
});

app.listen(3000, () => {console.log('App is listening on port 3000!')});
```
