typedef struct {
    EVP_CIPHER_CTX *ctx;
} Encryptor;

void handleErrors(void) {
    ERR_print_errors_fp(stderr);
    abort();
}

Encryptor initEncryption(const char* key, const char* iv, int mode) {
    EVP_CIPHER_CTX *ctx;
    Encryptor encryptor;

    if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();

    if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, (unsigned char*)key, (unsigned char*)iv))
        handleErrors();

    encryptor.ctx = ctx;
    return encryptor;
}

int updateEncryption(Encryptor* encryptor, unsigned char *plaintext, int plaintext_len, 
                     unsigned char *ciphertext) {

    if(1 != EVP_EncryptUpdate(encryptor->ctx, ciphertext, &len, plaintext, plaintext_len))
        handleErrors();

    return len;
}

int finalizeEncryption(Encryptor* encryptor, unsigned char *ciphertext) {

    if(1 != EVP_EncryptFinal_ex(encryptor->ctx, ciphertext, &len)) 
        handleErrors();

    return len;
}

void freeEncryption(Encryptor* encryptor) {
    EVP_CIPHER_CTX_free(encryptor->ctx);
}
```

Please note that this is a basic example and does not cover error handling, thread safety, modularity, cloud based key management or other advanced features required in your task. The actual implementation will be much more complex considering the various design choices and trade-offs. It's also recommended to use an established encryption library for real world applications due to potential security vulnerabilities.
']

