        std::cerr << "Failed to create producer: " << errstr << std::endl;
        exit(1);
    }

    std::string topic_name = "my-topic";
    RdKafka::Topic *topic = RdKafka::Topic::create(producer, topic_name, tconf, errstr);
    if (!topic) {
        std::cerr << "Failed to create topic: " << errstr << std::endl;
        exit(1);
    }

    std::string message = "Hello, Kafka!";
    RdKafka::ErrorCode resp = producer->produce(topic, RdKafka::Topic::PARTITION_UA, RdKafka::Producer::RK_MSG_COPY, const_cast<char *>(message.c_str()), message.size(), NULL, NULL);
    if (resp != RdKafka::ERR_NO_ERROR) {
        std::cerr << "Produce failed: " << RdKafka::err2str(resp) << std::endl;
        exit(1);
    }

    producer->flush(5000); // Wait for messages to be delivered (sync)

    delete topic;
    delete conf;
    delete tconf;
    delete producer;

    return 0;
}
