            // Process payment using the payment gateway
            PaymentResult paymentResult = null;
            int retryCount = 0;
            do {
                try {
                    paymentResult = paymentGateway.processPayment(cart, order);
                } catch (Exception e) {
                    // Log error and wait before retrying
                    Thread.sleep(5000);
                    ++retryCount;
