    struct ValueType {
        std::chrono::system_clock::time_point timestamp;
        std::string value;
        std::map<std::string, std::string> tags;
    };

private:
    std::map<std::string, ValueType> store_;
    mutable std::shared_mutex mutex_;

public:
    void set(const std::string& key, const ValueType& value) {
        std::lock_guard<std::shared_mutex> lock(mutex_);
        store_[key] = value;
    }

    ValueType get(const std::string& key) const {
        std::shared_lock<std::shared_mutex> lock(mutex_);
        auto it = store_.find(key);
        if (it != store_.end()) {
            return it->second;
        } else {
            throw std::runtime_error("Key not found");
        }
    }

    void asyncSet(const std::string& key, const ValueType& value) {
        std::thread([this, key, value]() {
            set(key, value);
        }).detach();
    }
};
```
