        } \
    } while (0)
```

2. Semaphore Management:
```c
#include <sys/sem.h>
int createSemaphore() {
    int semid = semget(IPC_PRIVATE, 1, IPC_CREAT | 0666);
    ERROR_HANDLING(semid, "Failed to create semaphore");
    return semid;
}
void destroySemaphore(int semid) {
    int err = semctl(semid, 0, IPC_RMID);
    ERROR_HANDLING(err, "Failed to destroy semaphore");
}
```

