```javascript
const express = require('express');
const passport = require('passport');
const Strategy = require('passport-local').Strategy;
const session = require('express-session');

// Initialize Passport
passport.use(new Strategy((username, password, done) => {
    User.findOne({ username: username }, (err, user) => {
      if (err) return done(err);

      // Validate password here...

      return done(null, user);
    });
}));

passport.serializeUser((user, done) => {
  done(null, user._id);
});

passport.deserializeUser((id, done) => {
  User.findById(id, (err, user) => {
    done(err, user);
  });
});

const app = express();
app.use(session({ secret: 'secret', resave: false, saveUninitialized: true }));
app.use(passport.initialize());
app.use(passport.session());

// Multi-tenancy middleware that would be used on all routes or a router level
function ensureTenant(req, res, next) {
  const tenantId = req.headers['x-tenant-id']; // Assuming we are passing the tenant ID in headers

  if (!tenantId || !tenants.includes(tenantId)) {
    return res.status(403).json({ error: 'Invalid tenant' });
  }

  req.tenant = getTenantConfig(tenantId); // Get tenant specific config (e.g., db connection, etc.)

  next();
}
app.use(ensureTenant);

// Route definitions...
```

This code implements a basic authentication flow using Passport.js and assumes that you have a mechanism to get/validate users in your database and the tenant configurations. Also, it uses express-session for session management which is not suitable for production grade applications but works well for a prototype or a simple application like this one.

