["Here's a basic outline of how you could approach this task using Node.js with Promises for asynchronous file reading and processing:

```javascript
const fs = require('fs');
const readline = require('readline');
const https = require('https');

class BookMentionsService {
  constructor(apiUrl) {
    this.bookNamesCache = new Set(); // Cache to hold validated book names from external API
    this.apiUrl = apiUrl;
  }

  fetchBooks() {
    return new Promise((resolve, reject) => {
      https.get(this.apiUrl, res => {
        let data = '';

        res.on('data', chunk => {
          data += chunk;
        });

        res.on('end', () => {
          const booksData = JSON.parse(data);

          for (let book of booksData) {
            this.bookNamesCache.add(book.name.toLowerCase());
          }

          resolve();
        });
      }).on('error', reject);
    });
  }

  validateBook(bookName) {
    return this.bookNamesCache.has(bookName.toLowerCase());
  }

  processFile(filePath, filterCriteria = {}) {
    const inputStream = fs.createReadStream(filePath);

    return new Promise((resolve, reject) => {
      const rlInterface = readline.createInterface({input: inputStream});

      let bookMentions = {};

      rlInterface.on('line', line => {
        for (let word of line.split(/\W+/)) { // Split by non-alphanumeric characters
          if (this.validateBook(word) && (!filterCriteria.book || filterCriteria.book === word)) {
            bookMentions[word] = (bookMentions[word] || 0) + 1;
          }
        }
      });

      rlInterface.on('close', () => {
        resolve(this.getTopBooks(bookMentions, filterCriteria.topN));
      });
    });
  }

  getTopBooks(mentions, topN = 10) {
    let books = Object.keys(mentions);

    books.sort((a, b) => mentions[b] - mentions[a]); // Sort by frequency in descending order

    return books.slice(0, Math.min(topN, books.length)); // Return top N or all if there are less than N
  }
}
```
In this code, the `BookMentionsService` class handles processing of large text documents and integrates with an external API to validate book names. It uses streams for file reading and event-driven programming for asynchronous processing. Progress tracking is implicitly handled by Node.js's built-in streaming APIs. 

