    }

    private String getToken() {
        HttpHeaders headers = new HttpHeaders();
        headers.setBasicAuth("client_id", "client_secret");

        MultiValueMap<String, String> body = new LinkedMultiValueMap<>();
        body.add("grant_type", "password");
        body.add("username", "employee_username");
        body.add("password", "employee_password");
        body.add("scope", readScope);

        HttpEntity<MultiValueMap<String, String>> entity = new HttpEntity<>(body, headers);

        ResponseEntity<String> response = restTemplate.exchange(oauth2TokenEndpoint, HttpMethod.POST, entity, String.class);

        // Process the OAuth2 token response and return it
    }

    public Employee getEmployeeDetails(int employeeId) {
        redis.clients.jedis.Jedis jedis = jedisPool.getResource();
        String key = "employee_" + employeeId;

        // Check cache first
        if (jedis.exists(key)) {
            return SerializationUtils.deserialize(jedis.get(key.getBytes()));
        }

        HttpHeaders headers = new HttpHeaders();
        String token = getToken();
        headers.setBearerAuth(token);

        HttpEntity<String> entity = new HttpEntity<>(headers);

        ResponseEntity<Employee> response = restTemplate.exchange(databaseUrl + "/employees/" + employeeId, HttpMethod.GET, entity, Employee.class);

